		["{zone:1448} is north of {zone:1440}."] = "{zone:1448}位于{zone:1440}北边。",
		["{zone:2482} is reached from {zone:1452} through {area:2256} in the south. It is Forever's endgame leveling zone."] = "从{zone:1452}经由南部的{area:2256}到达{zone:2482}。这是 Forever 的终局升级地区。",
} end)()
t.guides["forever/exploration/zephras-isle"] = (function() return {
		["Exploration: {zone:2521}"] = "探索：{zone:2521}",
		["Skyborne start here. Everyone else takes a skyboat, about every five minutes; either faction may take either one."] = "天裔从这里开始。其他人乘坐天空飞船，约每五分钟一班；两个阵营都可以乘坐任意一艘。",
		["The skyboat leaves the cliffs south of {area:17045}, north of {zone:1456} (another flies from {area:279})."] = "天空飞船从{zone:1456}北边、{area:17045}南边的悬崖出发（另一艘从{area:279}起飞）。",
		["The skyboat leaves the north side of {area:279} in the {zone:1416} (another flies from north of {zone:1456})."] = "天空飞船从{zone:1416}{area:279}的北侧出发（另一艘从{zone:1456}北边起飞）。",
		["any one of these names counts"] = "以下任意一个名称都算",
} end)()
t.guides["forever/horde/02-the-barrens"] = (function() return {
		["Back down the beach, past the pirate camp: the crate of boots and the fragile crate with the lens sit at its south end."] = "沿海滩往回走，经过海盗营地：一箱靴子和装着镜片的易碎品箱在营地南端。",
		["Back to the Razormane camp. Geomancers and Defenders hold its eastern half; {npc:3438} walks among them."] = "回到钢鬃营地。钢鬃地卜师和钢鬃防御者占据营地东半部；{npc:3438}在他们中间走动。",
		["Back west along the road."] = "沿道路向西返回。",
		["East to the {area:1703}; {npc:9316} stands at the camp just south of it."] = "向东前往{area:1703}；{npc:9316}站在其南边不远的营地。",
		["East to {area:392}, on the coast."] = "向东前往海岸上的{area:392}。",
		["Follow the road east to the outpost above the {area:814}."] = "沿道路向东前往{area:814}上方的哨站。",
		["Follow the road south-east to {area:392} on the coast."] = "沿道路向东南前往海岸上的{area:392}。",
		["Oasis Snapjaws crawl around {area:387}, south-west of the {area:380}, and around the {area:388}."] = "{npc:3461}在{area:380}西南方的{area:387}周围和{area:388}周围爬行。",
		["Razormane camp"] = "钢鬃营地",
		["South to {npc:3389}'s watch post on the Kolkar border."] = "向南前往{npc:3389}在科卡尔边界的哨站。",
		["South-east of the {area:380}. Test the seeds at the bubbling fissure on the oasis' east bank."] = "在{area:380}东南方。在绿洲东岸冒泡的裂缝处测试种子。",
		["The Savannah Prowlers hunt the plains between town and the Razormane camp to the east. In the camp, Water Seekers and Thornweavers hold the western half, Hunters the middle; the supply crates sit at its eastern end."] = "草原徘徊者在镇子和东边钢鬃营地之间的平原上狩猎。营地里，钢鬃寻水者和钢鬃织棘者占据西半部，钢鬃猎手在中部；补给箱在营地东端。",
		["The pools lie just north of {npc:3389}. Walk into the water to explore them; the Laden Mushrooms for Helbrim grow around them. Kill every Kolkar you pass for bracers."] = "水池就在{npc:3389}北边。走进水里即可探索；给赫布瑞姆的丰满的蘑菇长在水池周围。杀死途中的每个科卡尔半人马获取护腕。",
		["The tool buckets with the slugs lie around the Venture Co. drill site in the {area:382}, east of {npc:9316}."] = "装有高强度齿轮的工具桶散落在{npc:9316}东边{area:382}中的风险投资公司钻探点周围。",
		["Thunder Lizards and Lightning Hides graze just across the bridge below {area:379}."] = "雷霆蜥蜴和闪电蜥蜴就在{area:379}下方桥对面吃草。",
		["Thunder lizards across the river"] = "河对岸的雷霆蜥蜴",
		["Zhevra"] = "斑马",
		["Zhevra Runners graze north and east of town."] = "快步斑马在镇子北边和东边吃草。",
		["{area:1898} cultists"] = "{area:1898}的祭司",
		["{area:380} is your base for this guide. Everyone you need stands within a few steps of the inn."] = "{area:380}是本指南的大本营。你要找的人都在旅店几步之内。",
		["{npc:3442} in {area:392}: later, on the way"] = "{area:392}的{npc:3442}：稍后，顺路",
		["{npc:3442}: the console is in the {area:382}, later"] = "{npc:3442}：控制台在{area:382}，稍后",
		["{npc:3449}: the harpies come later, in the {area:383}"] = "{npc:3449}：鹰身人稍后再打，在{area:383}",
		["{npc:5878} camps beside the road east toward {area:392}."] = "{npc:5878}在向东通往{area:392}的路旁扎营。",
		["{npc:5878} camps beside the road from the {area:380} to {area:392}. The {object:58369} sits in the south of the Razormane camp just north of him."] = "{npc:5878}在从{area:380}到{area:392}的路旁扎营。{object:58369}在他北边不远的钢鬃营地南部。",
		["{npc:5900} makes {item:6636} from the tar and pouch. Use it by the brazier next to him to reveal the {npc:5893}, kill it for the {item:6655}, then place the ember in the brazier."] = "{npc:5900}用焦油和材料袋制作{item:6636}。在他旁边的火盆处使用它，显现出{npc:5893}，杀死它获得{item:6655}，然后把余烬放进火盆。",
		["{npc:5900} waits on the riverbank south of {area:379}, across the bridge."] = "{npc:5900}在{area:379}南边、桥对面的河岸上等候。",
		["{npc:5907} stands on the ridge north of the Razormane camp."] = "{npc:5907}站在钢鬃营地北边的山脊上。",
		["{npc:5907}: {npc:2523}, your {item:5176} and the {item:263412}"] = "{npc:5907}：{npc:2523}、你的{item:5176}和{item:263412}",
		["{quest:1492}, on the dock"] = "{quest:1492}，在码头上",
		["{quest:3301}: the {area:228} in {zone:1421}, next guide"] = "{quest:3301}：{zone:1421}的{area:228}，下一份指南",
} end)()
t.guides["forever/horde/03-silverpine-forest"] = (function() return {
		["At the {area:2362}"] = "在{area:2362}",
		["Fly to {area:1638}: {npc:3033} trains you on {area:1639}. Skyborne: fly back to {zone:1454} for the zeppelin afterwards."] = "飞往{area:1638}：{npc:3033}在{area:1639}训练你。天裔：之后飞回{zone:1454}乘坐飞艇。",
		["Follow the lake shore south-east and swim out to {area:172}. Rot Hide gnolls cover the island; every type drops ichor. Stay out of {area:235} on its north side unless you go for the optional niche: the gnolls there are level 18-22."] = "沿湖岸向东南走，游到{area:172}。岛上到处是腐皮豺狼人；每种都会掉落脓液。除非你要做可选的额外内容，否则别进入岛北侧的{area:235}：那里的豺狼人是18-22级。",
		["Follow the lake shore south-east toward {area:172}: the Vile Fin Shredders and Tidehunters along it drop the murloc eyes."] = "沿湖岸向东南朝{area:172}走：沿途的邪鳍切割者和邪鳍潮行者会掉落鱼人的眼球。",
		["Follow the road north-east to the Yoricks' house at {area:238}."] = "沿道路向东北前往{area:238}的尤瑞克家。",
		["Follow the road south. The {object:1627} sits beside it, north of Pyrewood."] = "沿道路向南。{object:1627}就在路边，焚木村北边。",
		["Keep it: Thork at the {area:380}"] = "留着它：交给{area:380}的索克",
		["Keep it: {npc:2216} in {area:272}, a later guide"] = "留着它：交给{area:272}的{npc:2216}，在之后的指南中",
		["Mottled Worgs"] = "杂斑座狼",
		["Mottled Worgs prowl the hills around the house."] = "杂斑座狼在房子周围的山丘上游荡。",
		["North again to the Yoricks' house."] = "再次向北前往尤瑞克家。",
		["North of the {area:228}. {npc:1983} haunts the {area:240}: kill it, then walk across the field."] = "在{area:228}北边。{npc:1983}在{area:240}出没：杀死它，然后穿过田野。",
		["South-east down the road to {area:233}. Protectors guard the outskirts and Mages the town; both drop pendants. Wizards and Watchers patrol the roads around it. Stay out of the middle, where {npc:2120} stands."] = "沿道路向东南前往{area:233}。达拉然保卫者守卫外围，达拉然法师守在镇里；两者都会掉落坠饰。达拉然巫师和达拉然卫士在周围的道路上巡逻。别进入镇中心，{npc:2120}就站在那里。",
		["Speak with {npc:10540}, in Grommash Hold"] = "与格罗玛什要塞里的{npc:10540}交谈",
		["Speak with {npc:3230}, in Grommash Hold"] = "与格罗玛什要塞里的{npc:3230}交谈",
		["The Vile Fin Lakestalkers and Oracles sit on the lake shore south of the {area:237}, east of the {area:228}."] = "邪鳍巡湖者和邪鳍智者在{area:237}南边、{area:228}东边的湖岸上。",
		["The cattails and speargrass grow along the water in the {object:172958}, east of the Drag."] = "香蒲和矛草长在暗巷区东边{object:172958}的水边。",
		["The {object:1593} lies at the ferry landing on the lake shore east of the {area:228}."] = "{object:1593}停在{area:228}东边湖岸的渡口。",
		["The {object:177790} lies on the coast west of the {area:240}. It holds the {item:15882} for {quest:30}."] = "{object:177790}位于{area:240}西边的海岸上。里面装着{quest:30}所需的{item:15882}。",
		["Vile Fin murlocs"] = "邪鳍鱼人",
		["Zeppelin to {zone:1454}"] = "乘飞艇前往{zone:1454}",
		["{area:1338} shore"] = "{area:1338}湖岸",
		["{area:233} comes later, on the southern loop"] = "{area:233}稍后在南线环路中前往",
		["{item:15877}, from a {object:177785} in the lake"] = "{item:15877}，来自湖中的{object:177785}",
		["{item:3317}: a rare drop from the gnolls"] = "{item:3317}：豺狼人的稀有掉落",
		["{npc:11798} in {area:2361} flies druids there; then fly on to {zone:1454} for the zeppelin"] = "{area:2361}的{npc:11798}载德鲁伊飞往那里；然后继续飞往{zone:1454}乘坐飞艇",
		["{npc:11799}, at the {area:2362}"] = "{npc:11799}，在{area:2362}",
		["{npc:1937}: for Quinn, on the road north at the end"] = "{npc:1937}：为了奎恩，最后在北边的路上",
		["{npc:1978} waits north-east of the house. Escort him back to {npc:1950}; worgs attack on the way."] = "{npc:1978}在房子东北边等候。护送他回到{npc:1950}那里；途中会有座狼袭击。",
		["{npc:2121}: {quest:516}, on the south loop"] = "{npc:2121}：{quest:516}，在南线环路中完成",
		["{npc:246152} trains Paladins in {area:159}, a short walk north up the road from the zeppelin towers. Come back down the same road for Silverpine."] = "{npc:246152}在{area:159}训练圣骑士，从飞艇塔沿道路向北步行不远即到。之后沿同一条路回来，前往银松森林。",
		["{npc:3348} and {npc:3347} run the alchemy shop in the Drag; {npc:11046} is next door."] = "{npc:3348}和{npc:3347}在暗巷区经营炼金商店；{npc:11046}就在隔壁。",
		["{npc:4949}, inside Grommash Hold"] = "{npc:4949}，在格罗玛什要塞里",
		["{npc:4949}: {quest:93739}, a tour of the Horde's leaders"] = "{npc:4949}：{quest:93739}，游览部落各位领袖",
		["{object:1599}, just east of the keep"] = "{object:1599}，就在城堡东边",
		["{quest:6127}: {area:384}, next guide"] = "{quest:6127}：{area:384}，见下一个指南",
} end)()
t.guides["forever/horde/04-the-barrens"] = (function() return {
		["Assist {npc:261366}: stay by him when {npc:261367} and the {area:21} marines come up the ridge"] = "协助{npc:261366}：当{npc:261367}和{area:21}水兵走上山脊时，待在他身边",
		["Bael'dun fortress"] = "巴尔丹城堡",
		["Bristleback camps"] = "刺背野猪人营地",
		["Dogran is chained up in the quilboar camp west of the road."] = "多格兰被锁在道路西边的野猪人营地里。",
		["Down the {area:458} to {area:378} again."] = "再次沿{area:458}向南前往{area:378}。",
		["Fill the {item:7766} at the quilboar watering hole"] = "在野猪人的水坑装满{item:7766}",
		["Fly to {area:1637} to train your level 20 ranks. {npc:3354} is in the {object:172958}, {npc:5892} in the {object:172957}."] = "飞往{area:1637}训练20级技能。{npc:3354}在{object:172958}，{npc:5892}在{object:172957}。",
		["Fly to {area:1638} and train your level 20 ranks: {npc:3033} is on {area:1639}."] = "飞往{area:1638}训练20级技能：{npc:3033}在{area:1639}。",
		["Fly to {area:1638} to train: {npc:3033} is on {area:1639}."] = "飞往{area:1638}训练：{npc:3033}在{area:1639}。",
		["Fly to {area:392}"] = "飞往{area:392}",
		["Follow the {area:458} south to {area:378}."] = "沿{area:458}向南前往{area:378}。",
		["He gives you the {item:15826}"] = "他会给你{item:15826}",
		["He offers {quest:1838} next (1838, level 30): it needs {area:1717} and sends you all over Kalimdor and the Eastern Kingdoms. The Warrior class guide {quest:1838} covers it."] = "他接下来会提供{quest:1838}（1838，30级）：它需要{area:1717}，还会让你跑遍卡利姆多和东部王国。战士职业指南{quest:1838}涵盖了它。",
		["Keep it: the {object:107045} is beside {area:272}"] = "留着它：{object:107045}在{area:272}旁边",
		["Keep it: {npc:12696} in {zone:1440}, next guide"] = "留着它：交给{zone:1440}的{npc:12696}，见下一个指南",
		["Keep it: {npc:5875} in {zone:1454}, at the end of this guide"] = "留着它：交给{zone:1454}的{npc:5875}，在本指南结尾",
		["North to the {area:383}. {npc:3682} camps below the hills; {npc:261366}, the hermit on the ridge behind him, has work for you only once {npc:3682} sends you up."] = "向北前往{area:383}。{npc:3682}在山下扎营；他身后山脊上的隐士{npc:261366}要等{npc:3682}派你上去后才会给你任务。",
		["On the way back down the {area:458} to {area:378}: the Razormane Raiders among the Bristleback camps, either side of the road north of the camp, carry {item:277277}. Hand them to {npc:3432} on your last {area:380} stop."] = "沿{area:458}返回{area:378}的路上：营地北边道路两侧刺背野猪人营地中的钢鬃掠夺者携带{item:277277}。最后一次在{area:380}停留时交给{npc:3432}。",
		["Pickpocket {npc:7287} for the tower key before opening the lockbox. Gallywix and his lockbox are at the top; the key does not open that box, which still needs Lockpicking. Gallywix is elite: grouping up is advised. If you postpone this optional job, resume it in the Class guide Poisons (Horde)."] = "打开保险箱前，先从{npc:7287}身上偷取塔楼钥匙。加里维克斯和他的保险箱在塔顶；这把钥匙打不开该保险箱，仍需开锁技能。加里维克斯是精英，建议组队。这段自选工作可以稍后从职业指南“毒药（部落）”继续。",
		["Tauren: the {npc:11957} waits on the southern hill above the bridge. Skyborne: the {npc:272054} stands south of the twin bridges. Then the dens east of the lake: leave your form, click the statue at the entrance for five minutes of stealth, keep clear of the spirits inside and take one of each relic; the {item:280680} lies at the foot of the white cat statue."] = "牛头人：{npc:11957}在桥上方的南边山丘上等候。天裔：{npc:272054}站在双桥南边。然后前往湖东边的兽穴：解除变形，点击入口处的雕像获得五分钟潜行，避开里面的灵魂，每种遗物各拿一件；{item:280680}在白色猎豹雕像脚下。",
		["The Bristleback quilboar camps spread over the plains north of {area:378}, either side of the {area:458}. Every Bristleback drops a tusk; {npc:3432}'s wife lies at the north edge. Keep one {item:5075}. {quest:883}, a grey kodo, sometimes wanders here: his hoof starts a quest."] = "刺背野猪人的营地遍布{area:378}北边的平原，位于{area:458}两侧。每个刺背野猪人都会掉落獠牙；{npc:3432}的妻子躺在北缘。留一个{item:5075}。{quest:883}是一头灰色科多兽，有时会在这里游荡：它的蹄子可以开始一个任务。",
		["The Venture Co. Overseers and Enforcers at the mine in the north-east corner of the zone drop the {item:5097}."] = "地区东北角矿洞的风险投资公司监督和风险投资公司执行者掉落{item:5097}。",
		["The dwarves' flying machine sits on its platform inside the dig site."] = "矮人的飞行器停在挖掘场内的平台上。",
		["The flying machine"] = "飞行器",
		["The {area:2363}"] = "{area:2363}",
		["The {object:172960} is the canyon under the {object:172982}."] = "{object:172960}是{object:172982}下方的峡谷。",
		["The {object:177792} lies at the north edge of the {area:382}, by the Venture Co. tower. It holds the {item:15883} for {quest:30}."] = "{object:177792}位于{area:382}北缘、风险投资公司的塔旁。里面装着{quest:30}所需的{item:15883}。",
		["Thunderhawk Cloudscrapers circle over the same plains south of the camp."] = "雷鹰破云者在营地南边同一片平原上空盘旋。",
		["Thunderheads graze on the plains just south of {area:378}. {quest:884}, a blue thunder lizard, roams among them: his Tailspike starts a quest."] = "电角蜥蜴在{area:378}正南的平原上吃草。{quest:884}是一只蓝色的雷霆蜥蜴，在它们中间游荡：它的尾刺可以开始一个任务。",
		["Twitching Antennae"] = "颤抖的触角",
		["Twitching Antennae from the silithid"] = "从异种蝎身上获取颤抖的触角",
		["Venture Co. tower"] = "风险投资公司的塔",
		["{item:15852}: Lost Barrens Kodos on the plains around the Kolkar camp"] = "{item:15852}：科卡尔营地周围平原上的落单的草原科多兽",
		["{item:15885}: use a half at the {area:2362}"] = "{item:15885}：在{area:2362}使用其中一半",
		["{item:2449} from {npc:3490}; herbalists pick it on the plains"] = "向{npc:3490}购买{item:2449}；草药师可以在平原上采集",
		["{item:2449}: herbalists pick it here"] = "{item:2449}：草药师可在这里采集",
		["{npc:11798} in {area:2361} flies druids there"] = "{area:2361}的{npc:11798}载德鲁伊飞往那里",
		["{npc:11802}: the welcome from {npc:3033}"] = "{npc:11802}：{npc:3033}的问候",
		["{npc:12296}: use the {item:15826} on them; they roam the plains all around the {area:380}"] = "{npc:12296}：对它们使用{item:15826}；它们在{area:380}周围的平原上游荡",
		["{npc:14242}, up in the tree just east of {npc:3341}"] = "{npc:14242}，在{npc:3341}正东的树上",
		["{npc:262119} and his marines hold the wrecked caravan south of {npc:261366}. The marines are linked: pulling one calls the rest. Pull from the edge and run; they leash short, so you can thin the camp one at a time before tackling the Corporal."] = "{npc:262119}和他的水兵守着{npc:261366}南边被毁的商队。这些水兵会互相联动，拉到一个会引来其余敌人。从边缘引怪后拉开距离，它们脱战距离较短，可以逐个清理营地，再对付下士。",
		["{npc:3341} waits in a small camp further south, on the road toward {area:359}."] = "{npc:3341}在更南边通往{area:359}的道路旁的一个小营地里等候。",
		["{npc:3389} stands at the Kolkar watch post just west of the {area:380}."] = "{npc:3389}站在{area:380}正西的科卡尔哨所。",
		["{npc:3394} stands in the Kolkar camp north-west of {npc:3389}."] = "{npc:3394}站在{npc:3389}西北的科卡尔营地里。",
		["{npc:3395} walks among the Kolkar at the {area:388} south-east of the {area:380}."] = "{npc:3395}在{area:380}东南的{area:388}，在科卡尔半人马中间走动。",
		["{npc:3396} leads the Kolkar on the west shore of {area:387}, south of {npc:3389}. Hand his head to {npc:3389} on your last {area:380} stop."] = "{npc:3396}率领着{area:387}西岸的科卡尔半人马，位于{npc:3389}南边。最后一次在{area:380}停留时把他的头颅交给{npc:3389}。",
		["{npc:3428}: the eggs are in the {area:390}, later"] = "{npc:3428}：蛋在{area:390}，稍后进行",
		["{npc:3429}, at the top of the tower"] = "{npc:3429}，在塔顶",
		["{npc:3429}. Keep it: Kadrak at the {area:1703}, next guide"] = "{npc:3429}。留着它：交给{area:1703}的卡德拉克，见下一个指南",
		["{npc:3430}, in the cage"] = "{npc:3430}，在笼子里",
		["{npc:3432} offers {quest:95774} once {quest:4921} is handed in"] = "{quest:4921}交还后，{npc:3432}会提供{quest:95774}",
		["{npc:3433}, at the north edge of the camp"] = "{npc:3433}，在营地北缘",
		["{npc:3442}, beside the wind rider master. Keep it: {quest:1483} is in Stonetalon, later"] = "{npc:3442}，在双足飞龙管理员旁边。留着它：{quest:1483}在石爪山脉，稍后进行",
		["{npc:3465} is chained inside the hold. Talk to him to start the escort and stay close: Theramore soldiers attack on the way out. He walks you back to {area:392}."] = "{npc:3465}被锁在要塞里。和他交谈开始护送，并紧跟着他：出去的路上会有塞拉摩士兵袭击。他会和你一起走回{area:392}。",
		["{npc:5878} camps beside the road east of the {area:380}."] = "{npc:5878}在{area:380}东边的路旁扎营。",
		["{npc:5899}, just west of {npc:3341}"] = "{npc:5899}，就在{npc:3341}西边",
		["{npc:5901} waits on the hill south of {area:392}, on your way north."] = "{npc:5901}在{area:392}南边的山上等候，就在你北上的路上。",
		["{npc:5909}, a few steps away"] = "{npc:5909}，就在几步之外",
		["{npc:6018} stands in the {object:172961}, on the city's west side."] = "{npc:6018}站在城西侧的{object:172961}。",
		["{npc:6018}: {npc:4606} in the {zone:1458}, two guides on"] = "{npc:6018}：{zone:1458}的{npc:4606}，见后面第二个指南",
		["{object:3972} poster"] = "{object:3972}告示",
		["{quest:2458}: {npc:7233}, by the {area:382}"] = "{quest:2458}：{npc:7233}，在{area:382}旁",
} end)()
t.guides["forever/horde/05-stonetalon-mountains"] = (function() return {
		["Back on the road south. Where it turns east into {area:287}, {npc:2214} waits at {area:285}."] = "回到向南的道路。在道路向东转入{area:287}的地方，{npc:2214}在{area:285}等候。",
		["Back to {npc:8582}"] = "回到{npc:8582}处",
		["Every Wrathtail naga along the strand north of the outpost drops heads."] = "哨站北边海滩上的每个怒尾纳迦都会掉落头颅。",
		["Follow the road north toward {area:467}. Antlered Coursers graze along the way; the Sap Beasts, Twilight Runners and Fey Dragons roam the woods below the Peak, and the Cenarion druids hold the grove there."] = "沿道路向北朝{area:467}前进。巨角鹿沿途吃草；腐蚀兽、夜行虎和灵龙在山峰下方的树林中游荡，塞纳里奥德鲁伊占据那里的树林。",
		["Follow the road west to {area:460}."] = "沿道路向西前往{area:460}。",
		["Gaea Dirt Mounds"] = "盖亚土堆",
		["Gaea Seeds"] = "盖亚之种",
		["Keep north on the road. The {npc:12862} waits at the Warsong lumber camp, south of Splintertree."] = "继续沿道路向北。{npc:12862}在碎木岗哨南边的战歌伐木营地等候。",
		["Naga heads"] = "纳迦头颅",
		["South-west of Sun Rock lies the burned {area:465}. Plant the Gaea Seeds in the dirt mounds on the valley floor; the fire elementals drop {item:16312}. Bloodfury Harpies and Ambushers nest on the north side, Slayers and Roguefeathers to the south."] = "烈日石居西南方是烧焦的{area:465}。把{item:16205}种在谷底的土堆里；火元素掉落{item:16312}。血怒鹰身人和血怒伏击者在北侧筑巢，血怒杀戮者和血怒游荡者在南侧。",
		["Sputtervalve in {area:392}: the next guide passes there"] = "{area:392}的斯布特瓦夫：下一份指南会经过那里",
		["Steer {npc:267214}'s {npc:271181} out of the ravine to the main road within four minutes; if the channel breaks, ask {npc:267214} again."] = "在四分钟内操控{npc:267214}的{npc:271181}离开峡谷到达主路；如果引导中断，再找{npc:267214}一次。",
		["The road climbs north as the {area:1076}. {quest:1483} has a hut where the road forks east to {area:461}."] = "道路向北攀升，即{area:1076}。{quest:1483}的小屋在道路向东分岔通往{area:461}的地方。",
		["The {npc:12864} patrols the road east of {area:428} toward the {area:430}."] = "{npc:12864}在{area:428}东边朝{area:430}方向的道路上巡逻。",
		["Use the {npc:212753} at the {object:645153} for a willing sacrifice and kill the {npc:212753} that answers. {quest:95883} is elite: grouping up is advised."] = "在{object:645153}使用{npc:212753}作为自愿的祭品，杀死回应的{npc:212753}。{quest:95883}是精英任务：建议组队。",
		["{area:431} is just north up the road."] = "{area:431}就在道路北边不远处。",
		["{item:16746}, from the {item:16783}"] = "{item:16746}，从{item:16783}中取得",
		["{item:271343}, from a {npc:1973}"] = "{item:271343}，来自{npc:1973}",
		["{item:277936}, from any Bloodfury harpy"] = "{item:277936}，来自任何血怒鹰身人",
		["{npc:11860}: Glittering Sunstones from the Bloodfury harpies"] = "{npc:11860}：从血怒鹰身人获取闪光的太阳石",
		["{npc:11860}: Grish is at the {area:1718}, in the next guide"] = "{npc:11860}：瑞什在{area:1718}，下一份指南",
		["{npc:11861}, beside {npc:11862}"] = "{npc:11861}，在{npc:11862}旁边",
		["{npc:11862}, up on the ledge"] = "{npc:11862}，在上方的岩架上",
		["{npc:12736} at Zoram'gar, at 27"] = "佐拉姆加的{npc:12736}，27级时",
		["{npc:2214}: Darthalia in {area:272}"] = "{npc:2214}：{area:272}的达萨利亚",
		["{npc:271181}, on the road"] = "{npc:271181}，在路上",
		["{npc:4198}, outside the gate"] = "{npc:4198}，在大门外",
} end)()
t.guides["forever/horde/06-hillsbrad-foothills"] = (function() return {
		["After returning Mission: Possible But Not Probable to Shenthul, bring {quest:2479} to {npc:2391} in {area:272}. Stay beside him until the brewing objective completes, then hand in the follow-up to learn Poisons. Finish it even if the Zanzil poison has already been removed; removing the debuff alone does not teach the skill."] = "向申苏尔交付“不可能完成的任务”后，带着“{quest:2479}”来{area:272}找{npc:2391}。留在他身边，等制药目标完成后再交后续任务，学会毒药。即使赞吉尔之触已经被解除，也要完成这一步；单纯解掉负面效果不会学会毒药。",
		["Bears, creepers and lions"] = "熊、食苔蛛和山地狮",
		["Drull's ball and chain"] = "德鲁尔的镣铐",
		["Fill the {item:7768} at the {object:107045} beside the inn"] = "在旅店旁的{object:107045}装满{item:7768}",
		["Follow the road south to the dwarf dig site at {area:359}. {npc:3421} hides at the south edge of the dig; {object:3646} sits at the bottom of the excavation."] = "沿道路向南前往{area:359}的矮人挖掘场。{npc:3421}躲在挖掘场南缘；{object:3646}在挖掘坑底部。",
		["From {zone:1454} (zeppelin from the towers outside the {zone:1458}) fly to {area:378}."] = "从{zone:1454}（在{zone:1458}外的塔上乘飞艇）飞往{area:378}。",
		["Hearth to {area:378} and fly to {area:392}. {quest:874} camps on the shore north of {area:392}."] = "用炉石回到{area:378}，飞往{area:392}。{quest:874}在{area:392}北边的海岸上扎营。",
		["Keep it: the {area:287} coast, later on the route"] = "留着它：{area:287}海岸，路线后面会去",
		["Masoj hides on the hillside above {area:290}, south of Durnholde, on the way down to the blossoms."] = "Masoj躲在{area:290}上方的山坡上，位于敦霍尔德城堡南边，就在下去采花的路上。",
		["Poison chain unfinished? Resume your current stage in the Class guide Poisons (Horde); completed quests do not need restarting. Arrange a group for Gallywix, finish the Hinott follow-up, then return to this leveling guide."] = "毒药任务线尚未完成的话，可从职业指南“毒药（部落）”中的当前阶段继续，无需重做已交的任务。找队伍处理加里维克斯并完成希诺特的后续，再回当前练级指南。",
		["South-west of Durnholde, the {item:3502} grow on the hillsides above the river."] = "在敦霍尔德城堡西南，{item:3502}长在河上方的山坡上。",
		["Take the zeppelin from the towers outside the {zone:1458} to {zone:1454} and train before you fly on."] = "在{zone:1458}外的塔上乘飞艇前往{zone:1454}，继续飞行前先训练。",
		["The farms east of {area:287} town. {npc:232} works the field by the northern farmhouse, {npc:2403} the one further south-east; Farmhands and Farmers are everywhere. {npc:2451} tends the field south of the farms."] = "{area:287}镇东边的农场。{npc:232}在北边农舍旁的田里干活，{npc:2403}在更东南的那片田；到处都是希尔斯布莱德雇农和希尔斯布莱德农夫。{npc:2451}照料农场南边的田地。",
		["The smithy"] = "铁匠铺",
		["The smithy stands in the middle of {area:287} town. {npc:2404} and his apprentices work at the forge; the {object:1736} is stacked beside it. {npc:2449} walks the street north of it."] = "铁匠铺在{area:287}镇中央。{npc:2404}和他的希尔斯布莱德见习铁匠在熔炉旁干活；{object:1736}堆在旁边。{npc:2449}在它北边的街上走动。",
		["The town hall is on the west side of {area:287}. {npc:2335} (30) and {npc:2448} are inside with the Town Registry; the Proclamation is pinned up beside it. Councilmen walk the town."] = "市政厅在{area:287}西侧。{npc:2335}（30级）和{npc:2448}在里面，旁边是希尔斯布莱德城镇文档；希尔斯布莱德宣言就贴在它旁边。希尔斯布莱德议员在镇上走动。",
		["The {area:288} lies south of {area:287} town. Miners work the tunnels; {npc:2305} (30) and {npc:2450} (29) are deep inside."] = "{area:288}在{area:287}镇南边。希尔斯布莱德矿工在坑道里干活；{npc:2305}（30级）和{npc:2450}（29级）在深处。",
		["Town hall"] = "市政厅",
		["West of Tarren Mill, Gray Bears, Forest Moss Creepers and Starving Mountain Lions roam the hills on the way down to the farms. The creepers drop {item:3477} rarely; you need only one."] = "在塔伦米尔西边，{npc:2351}、{npc:2350}和{npc:2384}在通往农场的山丘上游荡。食苔蛛很少掉落{item:3477}；你只需要一个。",
		["{area:272} is your base for this guide: the hearth brings you back here twice. Everyone stands around the town square."] = "{area:272}是本指南的据点：炉石会两次把你带回这里。所有人都站在镇广场周围。",
		["{item:3692}: the Peasants in the fields"] = "{item:3692}：田里的希尔斯布莱德农民",
		["{npc:2055}, in the Apothecarium"] = "{npc:2055}，在炼金房",
		["{npc:2055}, in the {zone:1458}"] = "{npc:2055}，在{zone:1458}",
		["{npc:2215}: orders for {npc:270438}, on the way to Durnholde"] = "{npc:2215}：给{npc:270438}的命令，在前往敦霍尔德城堡的路上",
		["{npc:2238}'s ball and chain"] = "{npc:2238}的镣铐",
		["{npc:2274} is {npc:232}'s dog, at the northern farmhouse in {area:286}."] = "{npc:2274}是{npc:232}的狗，在{area:286}北边的农舍旁。",
		["{npc:2388}: the last guide binds here, so this usually ticks at once"] = "{npc:2388}：上一份指南在这里绑定炉石，所以这一步通常会立即完成",
		["{npc:2391}: Poisons"] = "{npc:2391}：毒药",
		["{npc:3442}, by the docks in {area:392}"] = "{npc:3442}，在{area:392}的码头旁",
		["{npc:5899}'s hut stands on the ridge above the quilboar watering hole, south of {area:378}, on the way to {area:359}."] = "{npc:5899}的小屋在{area:378}南边野猪人水坑上方的山脊上，就在前往{area:359}的路上。",
		["{npc:5899}: the blue waterskin is filled in {zone:1440}, next guide"] = "{npc:5899}：蓝色水袋在{zone:1440}装满，见下一个指南",
		["{npc:5899}: the red waterskin from {area:272}"] = "{npc:5899}：{area:272}的红色水袋",
		["{quest:873}, a big threshadon, swims in the shallows off the {area:391}, east of {npc:3388}."] = "{quest:873}是一头巨大的鱼龙，在{area:391}外的浅水中游动，位于{npc:3388}东边。",
} end)()
t.guides["forever/horde/07-ashenvale"] = (function() return {
		["Back south to the camp, then up into {zone:1456} for the flight to {area:378}."] = "向南回到营地，然后上到{zone:1456}，飞往{area:378}。",
		["Back south-west to {area:421}. Befouled Water Elementals drift around its shores; the gazebo stands on the island, overlooking the Alliance outpost."] = "向西南回到{area:421}。污浊的水元素在湖岸周围漂浮；瞭望台在岛上，俯瞰着联盟的前哨站。",
		["Back west to Zoram'gar before heading east for good."] = "向西回到佐拉姆加前哨站，然后再彻底向东出发。",
		["Climb the path to the top of {area:2097}. {npc:10646} is held captive beside {npc:10896} (29): clear the guards and {npc:10896} first, then free her and protect her on the walk down; Grimtotem ambushers come at you on the way."] = "沿小路爬上{area:2097}顶部。{npc:10646}被囚禁在{npc:10896}（29级）旁边：先清掉守卫和{npc:10896}，再救出她并在下山路上保护她；途中会有恐怖图腾伏击者袭击你。",
		["Felmusk satyrs"] = "魔草萨特",
		["Follow the canyon east out of the mesas onto the salt flats. The goblins and gnomes of the {area:2240} are neutral and give quests to both factions."] = "沿峡谷向东离开石柱区，来到盐滩。{area:2240}的地精和侏儒是中立的，为两个阵营提供任务。",
		["Follow the main road east past {area:415} (Alliance: keep to the road). {npc:12678}, a big grizzly, roams the {area:418} south of the road, west of {area:421}. His paw starts the next hunt quest."] = "沿主路向东经过{area:415}（联盟据点：别离开道路）。{npc:12678}是一头巨大的灰熊，在道路南边、{area:421}西边的{area:418}游荡。它的爪子可以开始下一个狩猎任务。",
		["Galak centaurs"] = "加拉克半人马",
		["Gazebo"] = "瞭望台",
		["Gloomrise Toxin Samples, from the Gnawed Corpses"] = "暮升毒液样本，从{npc:264096}获取",
		["His crate is for Stranglethorn, later on the route"] = "他的箱子要送去荆棘谷，在路线后面",
		["Keep east on the road. {npc:12858} waits south-west of the Warsong lumber camp. He and his grunts storm the {area:2360}: let them take aggro and stay with {npc:12858} until {npc:12860} is dead."] = "继续沿道路向东。{npc:12858}在战歌伐木营地西南等候。他和他的步兵会猛攻{area:2360}：让他们吸引仇恨，跟着{npc:12858}直到{npc:12860}死去。",
		["Kill the {npc:10720} that comes for {npc:10638}"] = "杀死前来袭击{npc:10638}的{npc:10720}",
		["Naga brazier"] = "纳迦火盆",
		["North of the camp, spiders overrun the burial ground at {area:17044}. Use {npc:264074}'s {item:273015} on the Gnawed Corpses; the Spinners drop the {item:273181}. {npc:264082} sits at the north end: her {item:273658} starts {quest:96294}."] = "在营地北边，蜘蛛占据了{area:17044}的墓地。对{npc:264096}使用{npc:264074}的{item:273015}；那里的蜘蛛掉落{item:273181}。{npc:264082}在北端：她的{item:273658}可以开始{quest:96294}。",
		["North-west of Splintertree, the Felmusk satyrs camp in the woods. Every satyr can drop horns."] = "在碎木岗哨西北，魔草萨特在树林里扎营。每个萨特都可能掉落角。",
		["Ride the lift down, then follow the road east through the canyons to {area:484}, a Tauren village on top of the mesas. Its lift is on the north side."] = "乘升降梯下去，然后沿道路向东穿过峡谷前往{area:484}，那是一座建在石柱顶上的牛头人村庄。它的升降梯在北侧。",
		["Sapphires of Aku'Mai"] = "阿库麦尔蓝宝石",
		["South of Darkcloud, the harpies of {area:487}. {npc:4490} (31) walks among them: thin out the harpies around her before you pull her. The Screeching Harpies, Roguefeathers and Windcallers there are {npc:4877}'s."] = "在黑云峰南边是{area:487}的鹰身人。{npc:4490}（31级）在它们中间走动：引她之前先清掉她周围的鹰身人。那里的尖啸的鹰身人、尖啸的游荡者和尖啸的唤风者是{npc:4877}要的。",
		["Speak with {npc:3057}, in {area:1638}: {quest:93739}"] = "与{area:1638}的{npc:3057}交谈：{quest:93739}",
		["Take a lift down from {zone:1456}. The Earthen Ring camp stands north of the bluffs: {npc:264074}, {npc:264072} and {npc:259118}."] = "从{zone:1456}乘升降梯下去。大地之环的营地在高崖北边：{npc:264074}、{npc:264072}和{npc:259118}。",
		["Take the lift down. The egg lies in a nest on the canyon floor in one of three spots: south-east of the mesas (52.3,55.2), east (56.4,50.4) or south-west (37.6,56.1)."] = "乘升降梯下去。蛋在峡谷底部的一个巢里，位于三个地点之一：石柱东南（52.3,55.2）、东边（56.4,50.4）或西南（37.6,56.1）。",
		["The Earthen Ring"] = "大地之环",
		["The Foulweald furbolgs hold the woods east of {area:421}, south of the road. Place {item:16972} on the {object:178206} and guard it: the furbolgs come to tear it down. {npc:12918} comes last; his totem drops in the basket."] = "污林熊怪占据着{area:421}东边、道路南边的树林。把{item:16972}放在{object:178206}上并守护它：熊怪会来摧毁它。{npc:12918}最后出现；他的图腾会掉进篮子里。",
		["The Galak camps fill the canyon north of Freewind; Scouts, Wranglers and Windchasers share every camp. A lone {npc:10617} walks between the camps: kill him when you meet him, his note starts a quest for {area:2237}."] = "加拉克半人马的营地遍布乱风岗北边的峡谷；每个营地都有加拉克斥候、加拉克争斗者和加拉克逐风者。一个落单的{npc:10617}在营地之间走动：遇到就杀死他，他的信件可以开始一个{area:2237}的任务。",
		["The Sapphires are blue crystals on the walls of the tunnels leading to the {area:2797} portal, underground and outside the instance: swim down from the pit, under the wall, into the cave. The satyrs and naga in the tunnels are elite: grouping up is advised. The crystals respawn quickly, so there is no need to go deep."] = "阿库麦尔蓝宝石是通往{area:2797}传送门的坑道墙壁上的蓝色水晶，位于地下、副本之外：从坑里潜下去，从墙下游进洞穴。坑道里的萨特和纳迦是精英：建议组队。水晶刷新很快，不用深入。",
		["The Wanted poster beside {npc:10537}"] = "{npc:10537}旁的通缉告示",
		["The fountain stands in the middle of the {area:418}: use the {item:7767} there."] = "喷泉在{area:418}中央：在那里使用{item:7767}。",
		["The next guide flies on from here to {zone:1454}."] = "下一个指南从这里飞往{zone:1454}。",
		["The way to the Sapphires is through the sunken ruins at the north end of the strand: go down the stairs into the pit."] = "去阿库麦尔蓝宝石的路要穿过海滩北端沉没的废墟：沿台阶下到坑里。",
		["Thistlefur Hold"] = "蓟皮熊怪的巢穴",
		["West of Freewind, the Grimtotem camps below {area:2097}. The Secret Notes are in Document Chests at the south-east, south-west and north-west camps."] = "在乱风岗西边，恐怖图腾的营地在{area:2097}下方。密信在东南、西南和西北营地的文件箱里。",
		["for {npc:5901}, south of {area:392}: next guide"] = "交给{area:392}南边的{npc:5901}：见下一个指南",
		["{area:2797} ruins"] = "{area:2797}废墟",
		["{area:418} fountain"] = "{area:418}的喷泉",
		["{item:273181}, from Gloomrise Spinners"] = "{item:273181}，从{npc:264081}获取",
		["{item:273658}, from {npc:264082}"] = "{item:273658}，从{npc:264082}获取",
		["{npc:10377}, by the wind rider master"] = "{npc:10377}，在双足飞龙管理员旁边",
		["{npc:10428}'s next quest, Sacred Fire, ends in {zone:1456}, off this route. Skip it."] = "{npc:10428}的下一个任务（生命圣火）在{zone:1456}结束，不在本路线上。跳过它。",
		["{npc:12676}, a big nightsaber, prowls the woods south-east of the Warsong lumber camp. Her claw starts the next hunt quest."] = "{npc:12676}是一只巨大的夜刃豹，在战歌伐木营地东南的树林里潜行。它的爪子可以开始下一个狩猎任务。",
		["{npc:12677}, a shadow panther, stalks the woods around {area:426}, west of the Felmusk camp. Her head starts the next hunt quest."] = "{npc:12677}是一只暗影豹，在魔草萨特营地西边的{area:426}周围的树林里潜行。它的头颅可以开始下一个狩猎任务。",
		["{npc:12717} walks north up the strand to a naga brazier. Put the brazier out, then guard him through the naga waves until Vorsha is dead."] = "{npc:12717}沿着海滩向北走到一个纳迦火盆旁。熄灭火盆，然后在纳迦一波波来袭时保护他，直到鞭笞者沃尔沙死去。",
		["{npc:12717}: starts his escort at once"] = "{npc:12717}：立即开始护送",
		["{npc:12718}: only if you carry the manual pages"] = "{npc:12718}：仅当你带着手册书页时",
		["{npc:12736} offers a {area:2797} quest next; leave it unless you have a group."] = "{npc:12736}接下来会提供一个{area:2797}任务；除非你有队伍，否则别接。",
		["{npc:12759}, a corrupted water elemental, drifts in {area:421}. Her {item:16408} starts a quest for Splintertree."] = "{npc:12759}是一个被腐化的水元素，在{area:421}里漂浮。它掉落的{item:16408}可以开始一个碎木岗哨的任务。",
		["{npc:210995}, a Forever addition, stands on the west shore of {area:421} with three quick Dragonslayer quests."] = "{npc:210995}是Forever新增的NPC，站在{area:421}西岸，有三个简短的屠龙者任务。",
		["{npc:2986} stands on a mesa top east of the Galak camps. For the {quest:1149}, walk off the end of the planks beside him: you land safely."] = "{npc:2986}站在加拉克营地东边的一座石柱顶上。做{quest:1149}时，从他旁边的木板尽头走下去：你会安全落地。",
		["{npc:4454}: his letter goes to Martek in the {zone:1418}, around level 38"] = "{npc:4454}：他的信要交给{zone:1418}的马特克，大约38级时",
		["{npc:4499}, a hard-hitting rock elemental, walks the cliffs of {area:482}. {npc:4499} is elite: grouping up is advised."] = "{npc:4499}是一个攻击力很高的石元素，在{area:482}的悬崖上走动。{npc:4499}是精英：建议组队。",
		["{object:176344}, north-west camp"] = "{object:176344}，西北营地",
		["{object:176344}, south-east camp"] = "{object:176344}，东南营地",
		["{object:176344}, south-west camp"] = "{object:176344}，西南营地",
		["{object:19868} lies all over the flats north of the raceway. Scorpid Reavers and Sparkleshell Tortoises roam the north half, Salt Flats Scavengers circle overhead, and Saltstone Basilisks graze west of the track. The Crystalhides roam the middle of the flats and the Gazers (34-35, five levels above you: one at a time) the far south."] = "{object:19868}散落在赛道北边的盐滩上。恐蝎劫掠者和盐壳龟在北半部游荡，盐湖食腐鹫在空中盘旋，盐石蜥蜴在赛道西边吃草。盐石水晶蜥蜴在盐滩中部游荡，盐石凝视者（34-35级，比你高五级：一次引一只）在最南边。",
} end)()
t.guides["forever/horde/30-40/01-desolace"] = (function() return {
		["Back to {area:272}"] = "返回{area:272}",
		["Clam beds"] = "蚌床",
		["Daggerspine naga"] = "刺脊纳迦",
		["Daggerspine shore"] = "刺脊海岸",
		["Fly to {area:1637}"] = "飞往{area:1637}",
		["Fly to {area:1638} from Shadowprey and train with {npc:3033} on {area:1639}, then fly on to {zone:1454}."] = "从葬影村飞往{area:1638}，在{area:1639}找{npc:3033}训练，然后继续飞往{zone:1454}。",
		["Fly to {area:460}"] = "飞往{area:460}",
		["Fly to {area:484}. {npc:5905} hides in a small cave in the canyon wall north-east of the post."] = "飞往{area:484}。{npc:5905}躲在哨站东北峡谷崖壁上的一个小山洞里。",
		["Follow the road north out of {area:272} into the Alterac foothills. {quest:535} waits by the Syndicate camp; hand him the stout."] = "沿道路向北离开{area:272}，进入奥特兰克山麓。{quest:535}在辛迪加营地旁等候；把南海镇烈酒交给他。",
		["Follow the shore west past {area:271}'s bay; the Torn Fin murlocs camp on the beaches beyond it."] = "沿海岸向西经过{area:271}的海湾；碎鳍鱼人在海湾另一边的海滩上扎营。",
		["Keep north to {area:598}. The Oracles stand among the other naga at its north end; pull one at a time."] = "继续向北前往{area:598}。滑刃智者站在北端的其他纳迦中间；一次引一只。",
		["Kolkar ears"] = "半人马的耳朵",
		["Shadowstalker scalp"] = "巡影者的头皮",
		["Shindigger keg"] = "矿工烈酒酒桶",
		["Slitherblade Oracles"] = "滑刃智者",
		["South-west, the Cave and Ferocious Yetis (30-31) fill the caves in the hills west of {area:272}; about one in sixteen carries the rod."] = "在西南，洞穴雪人和凶恶的雪人（30-31级）占满了{area:272}西边山丘里的洞穴；大约十六分之一带着魔棒。",
		["Syndicate missives"] = "辛迪加信件",
		["Thaivand's next task ends at {area:271}'s graveyard and the magus offers a dungeon errand: leave both."] = "塞万德的下一个任务在{area:271}的墓地结束，而那位魔导师提供的是一个地下城差事：两个都别接。",
		["The Hatefury Shadowstalkers at {area:603} walk unseen until they strike; about one in three carries a scalp."] = "{area:603}的怨怒巡影者在攻击前都是隐形的；大约三分之一带着头皮。",
		["The Syndicate Footpads and Thieves (32-33) around the camps west of the road carry the missives; about one in three drops one."] = "道路西边营地周围的辛迪加劫匪和辛迪加窃贼（32-33级）携带信件；大约三分之一会掉落。",
		["The keg stands with a few others at the Syndicate camp on the south-east coast of {area:287}."] = "酒桶和另外几个酒桶一起放在{area:287}东南海岸的辛迪加营地里。",
		["The {area:279} traitors"] = "{area:279}的叛徒",
		["Torn Fin beach"] = "碎鳍海滩",
		["Torn Fin murlocs"] = "碎鳍鱼人",
		["Train"] = "训练",
		["Train your new spells."] = "训练你的新法术。",
		["Use {npc:11596}'s {item:13892} on an Aged, Dying or {npc:4702} in the graveyard and walk the tamed kodo back to {npc:11596}. Five kodos, one at a time."] = "对坟场里的老迈的科多兽、濒死的科多兽或{npc:4702}使用{npc:11596}的{item:13892}，把驯服的科多兽带回{npc:11596}那里。共五头，一次一头。",
		["for {npc:5901}: from Stranglethorn, next guide"] = "交给{npc:5901}：从荆棘谷前往，见下一个指南",
		["{area:2408} flight master"] = "{area:2408}的飞行管理员",
		["{item:3388}: auction house or an alchemist, for {quest:515}."] = "{item:3388}：拍卖行或炼金术士，用于{quest:515}。",
		["{item:3703}, for {npc:2333}"] = "{item:3703}，交给{npc:2333}",
		["{npc:11863} waits in the ruined tower of {area:2405}, inland to the south-east."] = "{npc:11863}在内陆东南方{area:2405}的废塔里等候。",
		["{npc:11877}: for {npc:715} in Stranglethorn"] = "{npc:11877}：交给荆棘谷的{npc:715}",
		["{npc:2229}: for the {zone:1413}, later on the route"] = "{npc:2229}：交给{zone:1413}，路线后面会去",
		["{npc:2770}: for {area:321} in Arathi, later on the route"] = "{npc:2770}：交给阿拉希高地的{area:321}，路线后面会去",
		["{npc:4949}, Grommash Hold, if you carry it"] = "{npc:4949}，在格罗玛什要塞，如果你带着它",
		["{npc:5395} stands in the post; {npc:5641} and {npc:4498} wait on the rise west of it, above the {area:596}."] = "{npc:5395}站在哨站里；{npc:5641}和{npc:4498}在哨站西边的高地上等候，俯瞰{area:596}。",
		["{npc:5639} waits in the Drag; {npc:5640} stands in the {object:172961} on the west side of the city. Skyborne: {npc:4949} waits in Grommash Hold, in the {object:172957}."] = "{npc:5639}在暗巷区等候；{npc:5640}站在城西侧的{object:172961}。天裔：{npc:4949}在{object:172957}的格罗玛什要塞里等候。",
		["{npc:5641}'s next errand sends you after a demon lord with an elite guard: skip it."] = "{npc:5641}的下一个差事要你去对付一个带着精英护卫的恶魔领主：跳过它。",
		["{npc:5641}'s next {quest:1431} sends you back to {zone:1454} for nothing: leave it."] = "{npc:5641}的下一个任务{quest:1431}让你白跑一趟{zone:1454}：别接。",
		["{npc:5892} stands in the {object:172957}."] = "{npc:5892}站在{object:172957}。",
		["{npc:5905} also starts Elemental Aid ({area:1717}), the 33-40 chain to The Tempest's Weapons: forever/class/shaman/call-of-air-horde."] = "{npc:5905}还会开始元素援助（{area:1717}），这是通往风暴武器的33-40级任务线：见萨满祭司职业指南“空气的召唤和风暴武器（部落）”。",
		["{npc:5905}: your {item:5178}"] = "{npc:5905}：你的{item:5178}",
		["{quest:515} needs a {item:3388}, an {skill:171} item: buy one at the auction house here if you can (or ask an alchemist). No potion: skip the Elixir steps in {area:287}."] = "{quest:515}需要一瓶{item:3388}，这是{skill:171}物品：如果可以，在这里的拍卖行买一瓶（或找炼金术士）。没有药水：跳过{area:287}的药剂步骤。",
		["{zone:1454} class quests"] = "{zone:1454}职业任务",
} end)()
t.guides["forever/horde/30-40/02-stranglethorn-vale"] = (function() return {
		["Back north to the camp."] = "向北回到营地。",
		["Back to {object:3202}."] = "返回{object:3202}。",
		["Elder tigers and Lashtail raptors"] = "老年猛虎和鞭尾迅猛龙",
		["Fly to {area:35}"] = "飞往{area:35}",
		["Fly to {object:3202}"] = "飞往{object:3202}",
		["Follow the road north out of {object:3202}; Nesingwary's hunting camp sits on the hill north-east of the river. From here on, keep every page of {quest:338} you loot: {npc:716} asks for them later."] = "沿道路向北离开{object:3202}；奈辛瓦里的狩猎营地在河东北边的山上。从现在起，留着拾取到的每一页{quest:338}：{npc:716}之后会要。",
		["Follow the road south to {area:35} at the southern tip of the vale and enter through the tunnel in the cliffs. Stay on the road: the jungle beside it is well above your level. {npc:2858}, the Horde flight master, waits on the upper deck."] = "沿道路向南前往山谷南端的{area:35}，从悬崖上的隧道进入。别离开道路：路旁丛林里的怪物比你高得多。部落飞行管理员{npc:2858}在上层甲板等候。",
		["Follow the road south to {object:3202}."] = "沿道路向南前往{object:3202}。",
		["Green Hills pages"] = "荆棘谷的青山书页",
		["Hearth to {area:35}"] = "用炉石回到{area:35}",
		["Nesingwary's camp"] = "奈辛瓦里的营地",
		["North-west of Grom'gol the {area:104} lies under the water off the coast. The {item:4094} rests on the sea floor by the sunken ruins; watch your breath and the murlocs."] = "{area:104}位于格罗姆高营地西北的近海水下。{item:4094}躺在沉没废墟旁的海底；注意呼吸和鱼人。",
		["Pages of The {item:2755} drop at about 1% each from the Bloodscalp and Skullsplitter trolls; keep every page you loot and look on the auction house for the rest. {npc:716} takes the chapters later in this guide."] = "{item:2755}的每一页从血顶巨魔和劈颅巨魔身上的掉率约为1%；留着拾取到的每一页，其余的去拍卖行找。{npc:716}会在本指南稍后收取各章节。",
		["Shadowmaw panthers"] = "深喉猎豹",
		["Stranglethorn Tigers and Panthers (32-33) roam the hills east of the camp, along the lake shore."] = "荆棘谷猛虎和黑豹（32-33级）在营地东边沿湖岸的山丘上游荡。",
		["The Lashtail Raptors (35-36) hunt the jungle just north-east of {object:3202}."] = "鞭尾迅猛龙（35-36级）在{object:3202}东北不远的丛林里捕猎。",
		["The Shadowmaw Panthers (37-38) stalk the jungle east of the Mosh'Ogg hills and north-east towards the lake; they strike from stealth. Loot every Green Hills page you find on the way."] = "深喉猎豹（37-38级）在莫什奥格山丘东边和东北方通往湖泊的丛林里潜行；它们会从潜行中发动攻击。沿途拾取你找到的每一页荆棘谷的青山。",
		["The Shadowmaw Panthers come much later, by {object:3202}"] = "深喉猎豹要很久以后才会遇到，在{object:3202}附近",
		["The camp by the river"] = "河边的营地",
		["The zeppelin lands at the tower on the west side of the camp."] = "飞艇降落在营地西侧的塔上。",
		["Venture Co. camp"] = "风险投资公司营地",
		["Zeppelin to {object:3202}"] = "乘飞艇前往{object:3202}",
		["{npc:2497}: for Arathi, later on the route"] = "{npc:2497}：交给阿拉希高地，路线后面会去",
		["{npc:5901}: {npc:3527} and your {item:5177}"] = "{npc:5901}：{npc:3527}和你的{item:5177}",
		["{npc:773}'s missing hunters' camp is Nesingwary's: walk among its tents and the investigation completes. River Crocolisks lie along the river below the camp."] = "{npc:773}失踪猎人的营地就是奈辛瓦里的营地：在帐篷间走一圈，调查就会完成。淡水鳄趴在营地下方的河边。",
} end)()
t.guides["forever/horde/30-40/03-arathi-highlands"] = (function() return {
		["Back to {area:321}"] = "回到{area:321}",
		["Boulderfist camp"] = "石拳营地",
		["Fleshstalker raptors"] = "猎兽龙",
		["Fly to {area:272}"] = "飞往{area:272}",
		["Fly to {object:3202}"] = "飞往{object:3202}",
		["Highland Fleshstalkers (36-37) hunt the southern highlands, a pack north of {area:316} and another on the plain to its west. Pull them one at a time."] = "高地猎兽龙（36-37级）在南部高地狩猎，一群在{area:316}北边，另一群在其西边的平原上。一次拉一只。",
		["Highland Striders roam the hills all around {area:321}; both they and the Thrashers further west drop the eyes."] = "高地阔步龙在{area:321}四周的山丘上游荡；它们和更西边的高地长尾龙都会掉落眼睛。",
		["Highland raptors"] = "高地迅猛龙",
		["Into the {zone:1418}"] = "进入{zone:1418}",
		["Keep north on the road; the chest lies in the {area:1517} dig site, at the foot of the ruins north-west of the road."] = "继续沿道路向北；箱子在{area:1517}挖掘场，位于道路西北方的废墟脚下。",
		["Lesser Rock Elementals"] = "次级石元素",
		["The Boulderfist Brutes camp outside the ogres' hall south of {area:321}; the Magus stand among them. Pull them one at a time."] = "石拳蛮兵在{area:321}南边食人魔大厅外扎营；石拳法师站在它们中间。一次拉一个。",
		["The inner circle lies south of the western circle, east of Stromgarde."] = "内部法阵在西部法阵南边、激流堡东边。",
		["The orc stronghold at the eastern end of the road. {npc:2851}, the wind rider master, stands by the gate."] = "道路东端的兽人要塞。双足飞龙管理员{npc:2851}站在大门旁。",
		["The small elementals drift across the flats just west of {npc:2921}'s camp. Every rock elemental in the zone can drop {npc:6868}'s Rock Elemental Shards: keep them."] = "小型元素在{npc:2921}营地正西的平地上飘荡。这个地区的每个石元素都可能掉落{npc:6868}要的石元素的碎片：留着它们。",
		["The stone's next task needs Fozruk, a level 42 elite: leave it."] = "石头的下一个任务需要击败42级精英弗兹鲁克：放着别管。",
		["The violet shards glow just off the road a short way west of {area:321}."] = "紫色碎片在{area:321}西边不远处的路旁发光。",
		["The {object:138492}"] = "{object:138492}",
		["The {object:2690}"] = "{object:2690}",
		["The {object:2691}"] = "{object:2691}",
		["The {object:2701} lie at the far end of the gorge."] = "{object:2701}在峡谷最深处。",
		["The {object:2702}"] = "{object:2702}",
		["Theldurin sits among the dwarven ruins at {area:345}, south of the {area:1877}."] = "塞尔杜林坐在{area:1877}南边{area:345}的矮人废墟中。",
		["Train while you are in the {zone:1458}: the trainers stand in the {object:36070}, the {object:36073} and the {object:36082} (Paladins: {npc:260093})."] = "趁在{zone:1458}时训练：训练师在{object:36070}、{object:36073}和{object:36082}（圣骑士：{npc:260093}）。",
		["West of the cove the Daggerspine Raiders and Sorceresses (38-40) hold the shore: pull them one at a time. The two wrecks lie in the shallows off it, the charts and logs inside them; the gems lie on the sea floor around the wrecks."] = "海湾西边，刺脊袭击者和刺脊巫师（38-40级）占据海岸：一次拉一个。两艘沉船在近海浅水中，海图和日志在船里；宝石在沉船周围的海底。",
		["Your trainer is in {area:1638}, one flight from {zone:1454}: {npc:3033} (Druids) on {area:1639}, {npc:246344} (Paladins). Fly on to the {area:380} from there."] = "你的训练师在{area:1638}，从{zone:1454}飞一次即到：{area:1639}的{npc:3033}（德鲁伊），{npc:246344}（圣骑士）。然后从那里飞往{area:380}。",
		["Zeppelin to {zone:1454}"] = "乘飞艇前往{zone:1454}",
		["for Helgrum in {area:75}, around level 42"] = "交给{area:75}的赫格拉姆，约42级",
		["for {npc:2487} in {area:35}, around level 44"] = "交给{area:35}的{npc:2487}，约44级",
		["{area:340} is the Horde fortress built into the cliffs at the zone's western edge."] = "{area:340}是建在地区西缘悬崖中的部落要塞。",
		["{npc:2771}'s next {quest:678} is against Boulderfist elites: leave it."] = "{npc:2771}的下一个{quest:678}要对付石拳精英：放着别管。",
		["{npc:2920}: only if you carry {item:2868} ({skill:164} or the Auction House)"] = "{npc:2920}：仅当你携带{item:2868}时（{skill:164}或拍卖行）",
		["{object:1661} has no Hunter or Shaman trainer: take the {zone:1454} zeppelin from the same tower instead and train in the city, then take the {zone:1458} zeppelin from the tower outside {zone:1454}'s main gate."] = "{object:1661}没有猎人或萨满祭司训练师：改从同一座塔楼乘飞艇前往{zone:1454}，在城里训练，然后从{zone:1454}正门外的塔楼乘飞艇前往{zone:1458}。",
		["{quest:1106}: Fizzle's letter from the {area:439}"] = "{quest:1106}：来自{area:439}的菲兹尔的信",
		["{zone:1458} trainers"] = "{zone:1458}的训练师",
} end)()
t.guides["forever/horde/30-40/04-dustwallow-marsh"] = (function() return {
		["Fly to {area:378}"] = "飞往{area:378}",
		["For {npc:2519} at {object:3202}, in the next guide"] = "交给{object:3202}的{npc:2519}，在下一个指南中",
		["Jarl lives in the {area:497} south-east of {area:502}."] = "加尔住在{area:502}东南的{area:497}。",
		["Maraudine totems"] = "玛洛迪图腾",
		["Mirefin murlocs"] = "黑鳍鱼人",
		["Slitherblade coast"] = "滑刃海岸",
		["Stinky Ignatz"] = "伊格纳兹",
		["Swamp Eye Jarl"] = "“沼泽之眼”加尔",
		["Take the road north at the fork to the ogre village of Brackenwall."] = "在岔路口沿道路向北，前往食人魔村庄蕨墙村。",
		["The Burning Blade hold the fortress north-west of {area:2407}. Use the {item:14523} on the {npc:11876} in the fortress to get the {item:13542}."] = "火刃氏族占据着{area:2407}西北的要塞。在要塞里对{npc:11876}使用{item:14523}，获得{item:13542}。",
		["The Mirefin murlocs crowd the coast east and north-east of {area:502}; every kind drops heads."] = "黑鳍鱼人聚集在{area:502}东边和东北边的海岸上；每种都会掉落头。",
		["The Slitherblade naga hold the coast north of {area:2405}, up to {area:598}. {npc:12369} guards the {quest:6027} at the far northern tip."] = "滑刃纳迦占据着{area:2405}北边直到{area:598}的海岸。{npc:12369}在最北端守护着{quest:6027}。",
		["The next guide takes you back to {zone:1434}."] = "下一个指南会带你回到{zone:1434}。",
		["only if you carry a {item:3853} ({skill:164} or the Auction House)"] = "仅当你带着{item:3853}时（{skill:164}或拍卖行）",
		["{npc:4503}, at the south edge of the village where the road comes in"] = "{npc:4503}，在道路进入村庄处的南缘",
		["{npc:4983} waits in the {area:2302} east of the village. Follow him to Reethe and keep him alive through the fight that breaks out."] = "{npc:4983}在村庄东边的{area:2302}等候。跟着他去找雷瑟，并在随后爆发的战斗中保护他活下来。",
		["{npc:6019} waits at the goblin camp on the west side of the {area:596}."] = "{npc:6019}在{area:596}西侧的地精营地里等候。",
		["{object:20985}, beside the manor"] = "{object:20985}，在庄园旁边",
		["{object:20985}, now that {npc:4791} has read the report"] = "{object:20985}，现在{npc:4791}已经读过报告了",
} end)()
t.guides["forever/horde/40-50/01-stranglethorn-vale"] = (function() return {
		["Boat to {area:35}"] = "乘船前往{area:35}",
		["Draenethyst crystals"] = "德莱尼水晶",
		["Fly to {object:3202}"] = "飞往{object:3202}",
		["Follow the coast south. The naga explorers wade along the shore and carry the reed bundles; the {object:759} bubbles in the hills just east of them."] = "沿海岸向南。纳迦探险者在岸边涉水而行，携带一捆海蛇草；{object:759}就在他们正东的山丘里冒泡。",
		["Hand Unbagwa the fangs and stay by him: he calls three waves of gorillas, then {npc:1514}. Fight them one at a time."] = "把猩猩牙交给安巴格瓦并待在他身边：他会召唤三波猩猩，然后是{npc:1514}。一次对付一个。",
		["His strongbox waits at his old camp north of {area:75}."] = "他的保险箱在{area:75}北边他原来的营地里。",
		["Jungle stalkers"] = "丛林捕猎者",
		["Leave town by the tunnel; the note lies in the pirates' cove just north of {area:35}."] = "从隧道出城；信件在{area:35}正北的海盗海湾里。",
		["Mistvale gorillas"] = "迷雾谷猩猩",
		["Noboru wanders the clearing south-west of the {area:76}; his cudgel starts a quest."] = "木棒诺博鲁在{area:76}西南的空地上游荡；他的木棒可以开始一个任务。",
		["North-east of Mistvale, Zanzil's followers camp in the jungle; every one of them can carry the mixture."] = "在迷雾谷东北，赞吉尔的追随者在丛林里扎营；他们每个人都可能携带赞吉尔的药剂。",
		["Pirate ghosts"] = "海盗幽灵",
		["Ride back east past {area:75} and follow the road south-east to the small Horde post on the shore."] = "向东骑回{area:75}，沿道路向东南前往岸边的部落小哨站。",
		["Ride north-east to the {area:76}. The crystals stand along the way up to {npc:5391}'s cage."] = "向东北骑往{area:76}。水晶分布在通往{npc:5391}笼子的路上。",
		["Ride west along the road to the draenei camp at the {area:657}, near the way in from {zone:1430}."] = "沿道路向西骑往{area:657}的德莱尼营地，靠近{zone:1430}的入口。",
		["Sawtooth crocolisks"] = "盐齿鳄鱼",
		["Skullsplitter warriors"] = "劈颅战士",
		["Take the road north out of {area:35}; Unbagwa sits on a hill in {area:1737}, east of the road."] = "沿道路向北离开{area:35}；安巴格瓦坐在道路东边{area:1737}的一座山丘上。",
		["The Bloodsail ships"] = "血帆海盗船",
		["The boat lands in {area:35}'s harbour. The quest givers stand on the boardwalks around the harbour and in the inn."] = "船停靠在{area:35}的港口。任务给予者站在港口周围的木栈道上和旅店里。",
		["The gorillas roam the valley around Unbagwa. The elders drop the giblets; any of them can drop a fang."] = "猩猩在安巴格瓦周围的山谷里游荡。老迈的猩猩掉落内脏；任何猩猩都可能掉落猩猩牙。",
		["The stalker raptors hunt the jungle south of {object:3202}, out towards the west coast."] = "丛林捕猎者迅猛龙在{object:3202}南边的丛林里捕猎，一直到西海岸。",
		["The three ghostly pirates haunt the jungle north of {area:35}, near Zanzil's camps: {npc:2535} and {npc:2536} stand together, {npc:2537} further east."] = "三个海盗幽灵在{area:35}北边、赞吉尔营地附近的丛林里出没：{npc:2535}和{npc:2536}站在一起，{npc:2537}在更东边。",
		["The three ships lie off the {area:43}. The crews are 42-45, Stillwater 45, Keelhaul 46 and {npc:2546} 48: at 41 this is a fight for a group, or for the end of the guide. If you go, swim out and pull the crew to the rail one at a time. A scroll, {quest:624}, lies on the ships' decks: take it."] = "三艘船停在{area:43}外的海面上。船员是42-45级，斯蒂沃特船长45级，尼哈鲁船长46级，{npc:2546}48级：41级时这是小队的战斗，或者留到本指南结束时再来。如果要去，就游过去，把船员一个个引到船舷边。船的甲板上有一张卷轴{quest:624}：拿上它。",
		["Venture Co. mine"] = "风险投资公司矿洞",
		["West of the expedition, the Bloodscalp chiefs {npc:1061} and {npc:1062} stand together in the ruins of Zul'Kunda. Clear their guards first, then pull them."] = "在远征队营地西边，血顶酋长{npc:1061}和{npc:1062}一起站在祖昆达废墟里。先清掉他们的守卫，再引他们。",
		["Zanzil's camps"] = "赞吉尔的营地",
		["Zul'Kunda"] = "祖昆达废墟",
		["Zul'Mamwe"] = "祖玛维废墟",
		["the {object:2076}"] = "{object:2076}",
		["{npc:5391} is held in the {area:76} in the swamp's north-east. Free him and follow him out, fighting off the swamp creatures that chase him."] = "{npc:5391}被关在沼泽东北的{area:76}。救出他并跟着他出去，击退追赶他的沼泽生物。",
} end)()
t.guides["forever/horde/40-50/02-feralas"] = (function() return {
		["Fly to {area:484}"] = "飞往{area:484}",
		["Fly to {object:3202}"] = "飞往{object:3202}",
		["Grimtotem camp"] = "恐怖图腾营地",
		["Hearth to {area:1099}"] = "用炉石回到{area:1099}",
		["Keep riding west to the coast. The Coast Crawl Deepseers and Snapclaws on the beaches drop OOX-22/FE's distress beacon about one kill in forty: if one drops, use it to start the quest."] = "继续向西骑到海岸。海滩上的海滩龙虾人先知和海滩利爪龙虾人大约每杀四十只掉落一个OOX-22/FE定位器：如果掉了，就使用它开始任务。",
		["Kodos: {npc:3685}, beside {npc:3690} in {area:222}."] = "科多兽：{npc:3685}，在{area:222}的{npc:3690}旁边。",
		["North of the gnolls the ogres hold a hilltop outpost; pull the ogre-magi to you. The cobalt is in the dirt mounds around the outpost, and the scroll lies on the ground inside it."] = "在豺狼人北边，食人魔占据着一座山顶前哨站；把食人魔法师引到你身边来打。戈杜尼钴矿石在前哨站周围的土堆里，戈杜尼卷轴就在前哨站里的地上。",
		["Ride north-east to the goblin harbour on the coast."] = "向东北骑往海岸边的地精港口。",
		["Ride south-west to the ogre ruins below {area:1105}. Shamans, warlocks and maulers fill them; the Mage-Lords at the southern end carry the orb."] = "向西南骑往{area:1105}下方的食人魔废墟。里面满是戈杜尼萨满祭司、戈杜尼术士和戈杜尼虐待者；南端的戈杜尼大法师携带宝珠。",
		["Riding at 40"] = "40级学骑术",
		["Skeletal horses: {npc:4731}, beside {npc:4773} in {area:159}."] = "骸骨军马：{npc:4731}，在{area:159}的{npc:4773}旁边。",
		["The Grimtotem tauren camp beside the sprite darters' grove; raiders, naturalists and shamans all carry horns."] = "恐怖图腾牛头人在小精龙的树林旁扎营；恐怖图腾袭击者、恐怖图腾博学者和恐怖图腾萨满祭司都携带恐怖图腾之角。",
		["The Zukk'ash hive burrows into the hills south-east of the camp; {quest:7731} waits in its deepest chamber."] = "祖卡什异种蝎的巢穴深入营地东南的山丘；{quest:7731}在最深处的洞室里等候。",
		["The battle map lies in the Woodpaw camp south of Mojache."] = "木爪作战地图在莫沙彻营地南边的木爪营地里。",
		["Wolves: {npc:3362}, beside {npc:4752}."] = "狼：{npc:3362}，在{npc:4752}旁边。",
		["Woodpaw battle map"] = "木爪作战地图",
		["Woodpaw north camp"] = "木爪北营地",
		["Your trainer is in {area:1638}: {npc:3033} (Druids) on {area:1639}, {npc:246344} (Paladins). Fly there from {zone:1454}, then on to {area:484}."] = "你的训练师在{area:1638}：{area:1639}的{npc:3033}（德鲁伊），{npc:246344}（圣骑士）。从{zone:1454}飞过去，然后继续飞往{area:484}。",
		["Zeppelin to {zone:1454}"] = "乘飞艇前往{zone:1454}",
		["for the {zone:1425}, around level 48"] = "交给{zone:1425}，大约48级时",
		["for {zone:1454}, around level 45"] = "交给{zone:1454}，大约45级时",
		["water pouches in your bags"] = "背包里的废土水袋",
		["{area:392} for the Felsteed"] = "前往{area:392}做地狱战马任务",
		["{npc:3690}, riding trainer"] = "{npc:3690}，骑术训练师",
		["{npc:4752}, riding trainer"] = "{npc:4752}，骑术训练师",
		["{npc:4773}, riding trainer"] = "{npc:4773}，骑术训练师",
		["{npc:8115}: for {zone:1454}, around level 45"] = "{npc:8115}：交给{zone:1454}，大约45级时",
		["{quest:2863}: one hour from now"] = "{quest:2863}：从现在起一小时内",
} end)()
t.guides["forever/horde/40-50/03-feralas"] = (function() return {
		["Dragon caves"] = "龙穴",
		["Forest walkers"] = "森林漫游者",
		["Frayfeather hippogryphs"] = "乱羽角鹰兽",
		["North-west along the road, the Rage Scar yetis live around the caves in the hills. Any of them can also drop a {quest:7738}, which starts a quest of its own."] = "沿道路向西北，狂暴的怒痕雪人住在山丘里的洞穴周围。它们也都可能掉落{quest:7738}，它可以开始一个单独的任务。",
		["Onyxia's eggs"] = "奥妮克希亚的蛋",
		["Rage Scar yetis"] = "怒痕雪人",
		["Ride back north to Brackenwall."] = "向北骑回蕨墙村。",
		["Ride north-west to the {area:1108}; {npc:14637} waits on the dock."] = "向西北骑往{area:1108}；{npc:14637}在码头上等候。",
		["Ride south-west to the {object:2555}, then east through the {area:511}. The Firemane scouts and ash tails roam its northern edge with the Searing hatchlings and whelps; the scalebanes guard the dragon caves further south-east. Mok'Morokk's snuff, grog and strongbox lie in the dragonkin camps."] = "向西南骑往{object:2555}，然后向东穿过{area:511}。火鬃斥候和火鬃灰尾龙人与灼热龙崽、灼热雏龙一起在北缘游荡；火鬃守卫守护着更东南的龙穴。莫格穆洛克的鼻烟、烈酒和保险箱都在龙人营地里。",
		["Ride west along the road; the scroll lies at the water's edge in the swamp's far west."] = "沿道路向西骑行；卷轴在沼泽最西边的水边。",
		["Sea elementals and sea sprays wash along the shore around the dock. Zap the giants with {item:18904} first: shrunken, they lose their elite strength. Shore striders wade in the water; the land walkers and cliff giants roam the hills further north."] = "海元素和巨型海元素沿着码头周围的海岸漂荡。先用{item:18904}电击巨人：被缩小后，它们就失去了精英的力量。海岸巨人在水中涉行；大地行者和峭壁巨人在更北边的山丘上游荡。",
		["South of the vale the Frayfeather hippogryphs roost on the slopes; nearly every one drops sinew and metallic fragments."] = "在山谷南边，乱羽角鹰兽栖息在山坡上；几乎每只都会掉落肌腱和金属碎片。",
		["South-west, the yetis den in {area:1105}; every yeti there can drop a thick hide."] = "在西南，雪人在{area:1105}筑巢；那里的每个雪人都可能掉落厚重的雪人皮。",
		["Sprite darters and forest walkers"] = "小精龙和森林漫游者",
		["The Eggs of Onyxia lie in the dragon caves in the {area:511}'s south-east, guarded by the scalebanes; smash five."] = "奥妮克希亚的蛋在{area:511}东南的龙穴里，由火鬃守卫看守；砸碎五个。",
		["The sprite darters flit over the grove just west of the camp and carry the {item:9589}; the Wandering Forest Walkers, a little further west, carry the Splintered Logs."] = "小精龙在营地正西的树林上空飞来飞去，携带{item:9589}；再往西一点的森林漫游者携带断裂的原木。",
		["The {area:511}"] = "{area:511}",
		["for the {npc:5598} in the {zone:1425}, around level 48"] = "交给{zone:1425}的{npc:5598}，大约48级时",
		["for the {zone:1425} owlbeasts, around level 48"] = "交给{zone:1425}的枭兽任务，大约48级时",
		["the {object:2555}"] = "{object:2555}",
		["{quest:7738}, a rare drop"] = "{quest:7738}，稀有掉落",
} end)()
t.guides["forever/horde/40-50/04-tanaris"] = (function() return {
		["Fly to {area:976}"] = "飞往{area:976}",
		["His next request needs the {item:10552} from elite cultists: leave it."] = "他的下一个请求需要精英信徒身上的{item:10552}：别接。",
		["Kalaran stands alone south of {area:1446}, at the edge of the Cauldron. Listen to his story."] = "卡拉然独自站在{area:1446}南边，大熔炉的边缘。听他讲他的故事。",
		["OOX-17/TN"] = "OOX-17/TN",
		["Only with the {item:11818}: back east to the {object:173265} at the dig site."] = "仅当你有{item:11818}时：向东回到挖掘场的{object:173265}。",
		["Ride back north to {area:1446}. Stay here: the next guide starts with the flight to {area:75}."] = "向北骑回{area:1446}。留在这里：下一个指南从飞往{area:75}开始。",
		["Scrimshank's gear"] = "谢申克的勘探设备",
		["South of the {area:982} the Dunemaul ogres hold their compound, with {npc:12046} at its eastern end. Dig up {quest:3161} ornaments between the fights."] = "在{area:982}南边，砂槌食人魔占据着他们的营地，{npc:12046}在营地东端。在战斗间隙挖出{quest:3161}饰物。",
		["The {area:247}"] = "{area:247}",
		["The {object:179827} board"] = "{object:179827}告示板",
		["West along the road south; {npc:7771} camps by the ruins at the {area:1938}. Put on his {item:9978}: it shows the buried ornaments, here and around the {area:983}."] = "沿道路向西再向南；{npc:7771}在{area:1938}的废墟旁扎营。戴上他的{item:9978}：它会显示埋在这里和{area:983}周围的饰物。",
		["West of Gadgetzan, use the {item:8584} beside the water hole in the troll camp."] = "在加基森西边，在巨魔营地的水坑旁使用{item:8584}。",
		["the {item:8526} grows in the {zone:1425}, around level 48"] = "{item:8526}生长在{zone:1425}，大约48级时",
		["the {object:173265}"] = "{object:173265}",
		["{item:11818}, a rare drop"] = "{item:11818}，稀有掉落",
		["{item:8623}, a rare drop"] = "{item:8623}，稀有掉落",
		["{npc:5955} waits in the valley. Walk him all the way to his wife {npc:6015} in {area:977}, north-east across the desert: stay close, slow down for him and fight off what attacks him. Do not mount or hearth out of his reach. {npc:8579} stands in the port too."] = "{npc:5955}在山谷里等候。一路带他到东北方沙漠另一头{area:977}的妻子{npc:6015}那里：紧跟着他，放慢速度等他，击退攻击他的敌人。别骑上坐骑或用炉石离开他的范围。{npc:8579}也站在港口里。",
		["{npc:5955}'s escort"] = "护送{npc:5955}",
		["{npc:7876}, beside the wind rider master"] = "{npc:7876}，在双足飞龙管理员旁边",
} end)()
t.guides["forever/horde/40-50/05-the-hinterlands"] = (function() return {
		["Back west to {area:350}; rangers and marksmen stay near the lodge, scouts and outrunners on the slopes south of it."] = "向西回到{area:350}；高原游侠和高原神射手待在旅舍附近，高原斥候和高原前锋在旅舍南边的山坡上。",
		["East of the village, the violet flower grows in the hills."] = "在村庄东边，紫色水生菇生长在山丘上。",
		["Fly to {area:272}"] = "飞往{area:272}",
		["Fly to {area:75}"] = "飞往{area:75}",
		["Highvale"] = "高原精灵",
		["His next request, going on to the {area:355}, is for a group."] = "他的下一个请求要前往{area:355}，需要组队。",
		["Huntsman Malkhor's skull lies on a pile below the Vilebranch ruins, his bones on a pile at the foot of {area:354}. The Vessels of Tainted Blood sit on the lower terraces, and {npc:14757} is held at the top. Keep to the paths: the trolls inside are elite."] = "猎户莫克霍尔的颅骨在邪枝废墟下方的一堆骨头上，他的骨头在{area:354}脚下的一堆上。污染之血容器放在下层平台上，{npc:14757}被关在最顶上。沿着小路走：里面的巨魔都是精英。",
		["North along the coast, {npc:14731}'s picnic basket is on the small island; a {npc:14748} guards it."] = "沿海岸向北，{npc:14731}的午餐篮在小岛上；一个{npc:14748}守着它。",
		["OOX-09/HL"] = "OOX-09/HL",
		["Ride all the way west to the Wildhammer town of {area:348} and place the message by the well in its centre. The town is full of Alliance guards: get in, place it and get out."] = "一路向西骑到蛮锤矮人的城镇{area:348}，把警告放在镇中央的水井旁。镇上全是联盟守卫：进去，放好，然后离开。",
		["Ride back north to the bloodmages."] = "向北骑回血法师那里。",
		["Ride west out of {area:75} and south through the canyon into the {zone:1419}; the two bloodmages stand by the road just inside."] = "从{area:75}向西出发，再向南穿过峡谷进入{zone:1419}；两位血法师就站在入口不远处的路旁。",
		["South of the lodge the Witherbark trolls hold their villages. Every one of them carries a skull: with twenty, use {item:15002} to make the Laden Pike, then plant it inside the village."] = "在旅舍南边，枯木巨魔占据着他们的村庄。他们每个都携带头皮：收集到二十个后，使用{item:15002}做成尼姆布亚的长矛，然后把它插在村子里。",
		["South-west again, the exile hides by the ruins of {area:353}."] = "再次向西南，流放者躲在{area:353}的废墟旁。",
		["The big turtles crawl along the beaches north of the village. {npc:2491}'s port bottles lie on these beaches too, but his quest is not on this route. A snapjaw can drop OOX-09/HL's distress beacon, rarely: keep it."] = "大海龟沿着村庄北边的海滩爬行。{npc:2491}的酒瓶也在这些海滩上，但他的任务不在本路线上。钳嘴龟可能掉落OOX-09/HL定位器，但很少见：留着它。",
		["The bloodmages"] = "血法师",
		["The crates of {item:8684} lie around the abandoned Horde camp at {area:351}, among the oozes."] = "一箱箱{item:8684}散落在{area:351}被遗弃的部落营地周围，混在软泥怪中间。",
		["The next guide starts here, at {area:3317}."] = "下一个指南从这里开始，在{area:3317}。",
		["The secret lies on the {area:307}, above the beach."] = "林吉的秘密在海滩上方的{area:307}。",
		["Their follow-ups ask for the same parts again for a buff item and pay no experience: leave them."] = "他们的后续任务又要同样的部件，换取一件增益物品，而且不给经验：别接。",
		["for {npc:6986} in {zone:1454}, around level 50"] = "交给{zone:1454}的{npc:6986}，大约50级时",
		["for {npc:7825} in the {zone:1458}, around level 50"] = "交给{zone:1458}的{npc:7825}，大约50级时",
		["{area:348} well"] = "{area:348}水井",
		["{item:8704}, a rare drop"] = "{item:8704}，稀有掉落",
		["{npc:14731}'s lunch"] = "{npc:14731}的午餐",
		["{npc:14757}, at the top of {area:354}"] = "{npc:14757}，在{area:354}顶上",
		["{npc:7801}'s camp"] = "{npc:7801}的营地",
} end)()
t.guides["forever/horde/40-50/06-azshara"] = (function() return {
		["Back north-east to {npc:8420}."] = "向东北回到{npc:8420}那里。",
		["Back to {area:1099}"] = "返回{area:1099}",
		["Back to {npc:11548} at the shrine; stay west of the {area:3137} guards."] = "回到神殿的{npc:11548}那里；待在{area:3137}守卫的西边。",
		["Back to {object:3202}"] = "返回{object:3202}",
		["Continue south to {area:35}. {npc:7406} has his workshop on the upper ring of the bay."] = "继续向南前往{area:35}。{npc:7406}的工作室在海湾的上层环道上。",
		["Fly from {area:1237} to {zone:1454}, walk out of the main gate to the zeppelin towers and take the zeppelin to {object:3202}."] = "从{area:1237}飞往{zone:1454}，从正门走到飞艇塔，乘飞艇前往{object:3202}。",
		["Follow the road north to {area:1237}, the Horde camp."] = "沿道路向北前往部落营地{area:1237}。",
		["Follow the road south; the basilisks bask on the rocks east of it in the middle of the jungle. Their shards drop often."] = "沿道路向南；蜥蜴在丛林中部道路东边的岩石上晒太阳。它们经常掉落碎片。",
		["Frayfeather Hippogryphs"] = "乱羽角鹰兽",
		["Ironjaw Basilisks"] = "铁腭蜥蜴",
		["Keep the deliveries for {npc:4046}, {npc:8659} and {npc:6522}: you pass {zone:1456}, {zone:1454} and the {zone:1458} later."] = "留着给{npc:4046}、{npc:8659}和{npc:6522}的货物：你之后会经过{zone:1456}、{zone:1454}和{zone:1458}。",
		["Keep {npc:8659}'s payment and Ag'tor's {quest:3504}: they go back to {area:1237} on a later visit."] = "留着{npc:8659}的报酬和阿格图的{quest:3504}：之后再去{area:1237}时交还。",
		["Keep {quest:3444}: {npc:7771}'s chest is opened on a later visit."] = "留着{quest:3444}：{npc:7771}的箱子要之后再来时才能打开。",
		["Only once all three robots are home"] = "仅当三个机器人都回家后",
		["Ride east along the road out of Splintertree. {npc:11548} waits at the {area:1235} just off the road, a few steps west of the Alliance's {area:3137}: come in from the west and keep clear of the Azshara Sentinels and Jarrodenus (elite)."] = "沿道路向东离开碎木岗哨。{npc:11548}在道路旁的{area:1235}等候，位于联盟{area:3137}西边几步远：从西边过去，避开艾萨拉哨兵和加罗迪努斯（精英）。",
		["Ride north-east to the goblin's camp on the cliffs above the {area:1227}."] = "向东北骑往{area:1227}上方悬崖上的地精营地。",
		["Ride south-west to the ruins. The four tablets lie among the ruins, guarded by Spitelash naga; any Siren or Myrmidon can carry {npc:8420}'s rune."] = "向西南骑往废墟。四块石板散落在废墟中，由恶鞭纳迦看守；任何恶鞭海妖或恶鞭侍从都可能携带{npc:8420}的符文。",
		["Ride west back to {area:1237}."] = "向西骑回{area:1237}。",
		["Sprite Darters"] = "小精龙",
		["Take the zeppelin back to {zone:1454}."] = "乘飞艇返回{zone:1454}。",
		["The Highborne ghosts haunt the ruins just north of the shrine; the Haldarr satyrs camp a little further north."] = "上层精灵的幽灵在神殿正北的废墟里出没；哈达尔萨特在更北一点的地方扎营。",
		["The Thunderhead Hippogryphs fly over the hills just south of {area:1237}."] = "雷首角鹰兽在{area:1237}正南的山丘上空飞翔。",
		["The blood elves' camp lies just south of {npc:8420}. His four pieces of equipment lie in the crates around the camp."] = "血精灵的营地就在{npc:8420}南边。他的四件设备在营地周围的箱子里。",
		["The faerie dragons flit around the woods just west of the camp. Use the vessel on each one you kill."] = "精灵龙在营地正西的树林里飞来飞去。对你杀死的每一只使用容器。",
		["The hippogryphs nest on the hills south-west of the camp. Kill one, then use the Muisek Vessel on its body."] = "角鹰兽在营地西南的山丘上筑巢。杀死一只，然后对它的尸体使用灵魂精华容器。",
		["The treants wander the forest roads between the camp and the middle of {zone:1444}; there are only a few, so look along the paths."] = "树人在营地和{zone:1444}中部之间的林间道路上游荡；数量很少，所以沿着小路找。",
		["The {object:2076} beside {npc:2519}"] = "{npc:2519}旁边的{object:2076}",
		["To {object:3202}"] = "前往{object:3202}",
		["Undamaged Hippogryph Feathers"] = "完好无损的角鹰兽羽毛",
		["Wandering Forest Walkers"] = "森林漫游者",
		["Xylem's tower stands on the cliff just north of {area:1237}; the path winds up its north side."] = "克希雷姆的塔建在{area:1237}正北的悬崖上；小路沿塔的北侧蜿蜒而上。",
		["Zeppelin to {zone:1454}"] = "乘飞艇前往{zone:1454}",
		["{npc:6986}, the Drag"] = "{npc:6986}，在暗巷区",
		["{npc:7876}'s tar and Pestlezugg's samples come from {zone:1449}."] = "{npc:7876}要的焦油和匹斯特苏格要的样本都来自{zone:1449}。",
		["{npc:7876}, beside the wind rider master"] = "{npc:7876}，在双足飞龙管理员旁边",
		["{npc:8395}, at the east edge of the camp: no experience, only a teleport to Azshara Tower"] = "{npc:8395}，在营地东缘：没有经验，只能传送到克希雷姆的法师塔",
		["{npc:8659}, the {object:172960}"] = "{npc:8659}，在{object:172960}",
		["{quest:3761} is gathered in the next guide; {npc:4046}'s payment goes back to {npc:8587} later."] = "{quest:3761}在下一个指南中收集；{npc:4046}的报酬之后交还给{npc:8587}。",
} end)()
t.guides["forever/horde/50-60/01-un-goro-crater"] = (function() return {
		["Back north-east to {area:251}."] = "向东北回到{area:251}。",
		["Back to {area:2268}"] = "返回{area:2268}",
		["Bridge into {area:254}"] = "通往{area:254}的桥",
		["Cross the south of the crater to the pylon on the western cliffs."] = "穿过环形山南部，前往西边悬崖上的水晶塔。",
		["Eastern Pylon"] = "东部水晶塔",
		["Fly to {area:340}"] = "飞往{area:340}",
		["Follow the cliffs south to {quest:3821}, the Firegut ogres' hill. {npc:9136}'s remains lie at its foot."] = "沿悬崖向南前往火腹食人魔的山丘{quest:3821}。{npc:9136}的遗骸在山脚下。",
		["Free Darrowshire Spirits: talk to them"] = "释放达隆郡居民的灵魂：和它们交谈",
		["From here on pick up every Power Crystal (blue, green, red, yellow) and every {quest:3761} pile you pass: 25 soil in all, 20 for Hamuul and 5 for Pestlezugg."] = "从现在起，捡起路过的每一块能量水晶（蓝色、绿色、红色、黄色）和每一堆{quest:3761}：总共25份土壤，20份给哈缪尔，5份给匹斯特苏格。",
		["Into the {zone:1427}"] = "进入{zone:1427}",
		["Keep {npc:10267}'s letter: {quest:4808} is in {area:2255}, {zone:1452}."] = "留着{npc:10267}的信：{quest:4808}在{zone:1452}的{area:2255}。",
		["Keep {npc:9118}'s {quest:4147} and {npc:8737}'s letter for later guides."] = "留着{npc:9118}的{quest:4147}和{npc:8737}的信，在之后的指南中使用。",
		["Keep {quest:5152}: Marlene lives at {area:197} in the {zone:1422}."] = "留着{quest:5152}：玛莱恩住在{zone:1422}的{area:197}。",
		["Lar'korwi Mates"] = "拉克维的配偶",
		["North of Torwa, a dead Threshadon lies by the water."] = "在托尔瓦北边，一头死去的蛇颈龙躺在水边。",
		["Northern Pylon"] = "北部水晶塔",
		["Out of the refuge"] = "离开避难所",
		["Pestlezugg's next quest needs the {npc:10041}, an elite boss. Skip it."] = "匹斯特苏格的下一个任务需要击败精英首领{npc:10041}。跳过它。",
		["Ride down the east side of the crater to the pylon on the eastern cliffs."] = "沿环形山东侧骑下去，前往东边悬崖上的水晶塔。",
		["Ride north back to {area:541}."] = "向北骑回{area:541}。",
		["Ride south back to the road and follow it east across the whole zone to {area:2268}."] = "向南骑回道路，沿路向东穿过整个地区前往{area:2268}。",
		["Stegodons and ravasaurs"] = "剑龙和暴掠龙",
		["Take a {object:176092} from the crate next to Derrington for {quest:5096}, done on the way back. Equip the {quest:5401}: Scourgestones only drop while you wear it."] = "从德灵顿旁边的箱子里拿一个{object:176092}，用于{quest:5096}，在回程时完成。装备{quest:5401}：只有佩戴它时才会掉落天灾石。",
		["Take the pass out of {area:340}'s west side into the {zone:1427}, then ride south across the gorge to the long bridge into {area:254}. Inside, follow the chain walkways down and leave through the southern exit; stay off the paths to the dungeon portals."] = "从{area:340}西侧的山口进入{zone:1427}，然后向南穿过峡谷，走上通往{area:254}的长桥。进去后沿着铁链走道往下走，从南边的出口离开；别走通往地下城传送门的路。",
		["The Gorishi hive"] = "格里什虫巢",
		["The Lar'korwi Mates prowl the jungle north-west of {npc:9619}."] = "拉克维的配偶在{npc:9619}西北的丛林里潜行。",
		["The doll's head and its two sides lie in the houses around {npc:10926}; join them from your bags."] = "洋娃娃的脑袋和两半身体在{npc:10926}周围的房子里；在背包里把它们拼起来。",
		["The expedition's lost equipment lies in the south-west jungle."] = "考察队丢失的研究设备在西南丛林里。",
		["The mountain lets you out beside {area:252}, full of 55-57 orcs. Follow the road east along the northern cliffs to the Horde camp at {area:251}."] = "从山里出来就在{area:252}旁边，那里满是55-57级的兽人。沿北边悬崖的道路向东，前往部落营地{area:251}。",
		["The next guide starts here, at the chapel's flight master."] = "下一个指南从这里的教堂飞行管理员处开始。",
		["The pylon stands on the slope east of the refuge."] = "水晶塔在避难所东边的山坡上。",
		["The raft lies on the shore of the south-eastern lake; the small pack sits in the water beside it."] = "破碎的木筏在东南湖泊的岸边；小背包就在旁边的水里。",
		["Use the Mangled Journal to start it"] = "使用被撕破的日记开始任务",
		["Western Pylon"] = "西部水晶塔",
		["With {npc:11063}'s quest in your log, slain Scourge sometimes leave a {npc:11064}; talk to it to free it. Kill undead on the ride south-west to {area:2262}."] = "任务日志里有{npc:11063}的任务时，被杀死的天灾军团有时会留下一个{npc:11064}；和它交谈来释放它。在向西南骑往{area:2262}的路上击杀亡灵。",
		["{item:11116}, a rare drop"] = "{item:11116}，稀有掉落",
		["{npc:10879}, the {object:36078}, beside the bat master"] = "{npc:10879}，在{object:36078}的蝙蝠管理员旁边",
		["{npc:10926}'s ghost stands in the ruins of {area:2262}, in the south-west."] = "{npc:10926}的鬼魂站在西南边{area:2262}的废墟里。",
		["{npc:6522}, the {object:36073}"] = "{npc:6522}，在{object:36073}",
		["{npc:8390}, the Apothecarium: the vials fill in {zone:1447} later"] = "{npc:8390}，在炼金房：瓶子之后在{zone:1447}装满",
		["{npc:9618}, just outside"] = "{npc:9618}，就在外面",
		["{npc:9619} camps in the south-east corner of the crater."] = "{npc:9619}在环形山的东南角扎营。",
		["{npc:9998}, at the entrance"] = "{npc:9998}，在入口",
		["{npc:9998}, at the refuge entrance"] = "{npc:9998}，在避难所入口",
		["{quest:3822} walks the caves and mine tunnels of {quest:3821}; if he isn't home, clear the ogres around the entrances until he comes back."] = "{quest:3822}在{quest:3821}的洞穴和矿道里走动；如果他不在，就清理入口周围的食人魔，直到他回来。",
} end)()
t.guides["forever/horde/50-60/02-felwood"] = (function() return {
		["Back north to {area:1763}. Fill {npc:10922}'s canteen at the corrupted moonwell in the middle of the southern camp."] = "向北回到{area:1763}。在南部营地中央被腐化的月亮井装满{npc:10922}的水壶。",
		["Derrington's watchtowers, Vandis' cauldron and {npc:11615}'s barrel are done on a later visit: keep them."] = "德灵顿的哨塔、范蒂丝的瘟疫之锅和{npc:11615}的木桶留到之后再来时完成：留着它们。",
		["Diseased Wolves"] = "生病的狼",
		["East of Bloodvenom Post, the cratered vale where the Entropic Beasts and Horrors roam. Kill two of each, then walk to each of the three fel-water craters."] = "在血毒岗哨东边，是{npc:9878}和热能恐兽游荡的坑洼山谷。每种各杀两只，然后走到三个邪能水坑的每一个那里。",
		["Follow the road north-east to {area:1767}. The Warpwood Moss Flayers and Shredders on the east side of the woods each carry a {item:11503}; Angerclaw Grizzlies and Felpaw Ravagers roam the same woods for Talo."] = "沿道路向东北前往{area:1767}。树林东侧的曲木食苔者和曲木撕裂者各带着一块{item:11503}；怒爪灰熊和魔爪掠夺者在同一片树林里游荡，是塔罗要的。",
		["Follow the road north-west. The south of {area:1763}, around its corrupted moonwell, is held by Shadow Council cultists, adepts, guardsmen and their hounds."] = "沿道路向西北。{area:1763}南部那口被腐化的月亮井周围被暗影议会的加德纳尔祭司、加德纳尔精兵、卫兵和恶犬占据。",
		["He camps by the {area:202}, south-east of {area:200}."] = "他在{area:200}东南的{area:202}旁扎营。",
		["Jadefire moonwell"] = "碧火月亮井",
		["Keep the branch: {npc:5770} is in {zone:1456}."] = "留着树枝：{npc:5770}在{zone:1456}。",
		["Keep {quest:5158}: {npc:5901} is in the {zone:1413}."] = "留着{quest:5158}：{npc:5901}在{zone:1413}。",
		["Keep {quest:8465} for {zone:1452}."] = "留着{quest:8465}去{zone:1452}。",
		["Knights and magi work the {area:192}; the medics and hunters camp south of it."] = "血色骑士和血色占星师在{area:192}干活；血色医护员和血色猎人在它南边扎营。",
		["Northern crater"] = "北部水坑",
		["Only if a {item:13140} dropped: use it to start the quest, then free {npc:11018} in her cage in {area:1770}, the cave at the north end of {area:1763}, and escort her out."] = "仅当掉落了{item:13140}时：使用它开始任务，然后到{area:1763}北端的洞穴{area:1770}里，把笼子里的{npc:11018}救出来，并护送她出去。",
		["Only if you rescued {npc:11018}: the succubus {npc:9518} waits in the middle of {area:1763}, beside the {npc:11020}."] = "仅当你救出了{npc:11018}时：魅魔{npc:9518}在{area:1763}中部，就在{npc:11020}旁边等候。",
		["Only with 5 Deadwood Headdress Feathers"] = "仅当你有5根死木头饰羽毛时",
		["Ride back south past {area:1763} to the corrupted moonwell of the Jadefire satyrs and fill {npc:9996}'s flasket there."] = "向南骑过{area:1763}，前往碧火萨特那口被腐化的月亮井，在那里装满{npc:9996}的小瓶。",
		["Ride north along the eastern hills; {npc:1855} lives in a small house by the {area:2619}, at the border with the {zone:1423}."] = "沿东边的山丘向北骑行；{npc:1855}住在{area:2619}旁的一间小房子里，就在与{zone:1423}的交界处。",
		["Ride north up the road again."] = "再次沿道路向北骑行。",
		["Ride north-west into Andorhal. {npc:10667} waits in the ruined inn on the west side of town; the skeletons inside are 54-57, so keep to the edges."] = "向西北骑进安多哈尔。{npc:10667}在城镇西侧被毁的旅店里等候；里面的骷髅是54-57级，所以沿着边缘走。",
		["Ride south-west past Felstone Farm and follow the road west back to the {area:152}."] = "向西南骑过费尔斯通农场，沿道路向西回到{area:152}。",
		["Ride west to the {area:192}; {npc:11610} hides on the hill north-east of it."] = "向西骑往{area:192}；{npc:11610}躲在它东北的山上。",
		["Ror stands at the far south end of {area:1761}."] = "洛尔站在{area:1761}最南端。",
		["Scarlet Crusade"] = "血色十字军",
		["Southern crater"] = "南部水坑",
		["Southern {area:1763}"] = "{area:1763}南部",
		["Take the kitten to the same moonwell and release it there; once it has turned into a {npc:10042}, bring it back to {npc:9996} and click on it to hand it over."] = "把小猫带到同一口月亮井并在那里放出它；它变成{npc:10042}后，把它带回{npc:9996}那里，点击它交给她。",
		["The Annals lie among the Musty Tomes in Andorhal's town hall; open them until you find the right one."] = "达隆郡的历史就在安多哈尔市政厅里的发霉的书籍中间；一本本打开，直到找到正确的那本。",
		["The Deadwood furbolg village just west of the tunnel. {npc:9462} (56) stands among them. {npc:11557}, a friendly furbolg, sits at the north end of the village."] = "隧道正西的死木熊怪村庄。{npc:9462}（56级）站在它们中间。{npc:11557}是一个友善的熊怪，坐在村庄北端。",
		["The Deadwood furbolg village lies just south of the Sanctuary. Every Deadwood kill also raises your {area:1769} reputation; keep the headdress feathers."] = "死木熊怪的村庄就在翡翠圣地正南。每杀一个死木熊怪也会提升你在{area:1769}的声望；留着死木头饰羽毛。",
		["The Horde camp just north of {area:1763}."] = "{area:1763}正北的部落营地。",
		["The Jadefire moonwell"] = "碧火月亮井",
		["The diary lies in the farmhouse, the cabinet stands inside and the outhouse is behind it. A {npc:10816} carries the outhouse key; {npc:10836} comes out when you open the outhouse and carries the cabinet key."] = "日记在农舍里，柜子在屋里，厕所在屋后。一个{npc:10816}带着厕所钥匙；打开厕所时{npc:10836}会出来，他带着柜子钥匙。",
		["The druids' camp is just past the border."] = "德鲁伊的营地就在边界过去一点。",
		["The road ends at {npc:15395}, outside the {area:1769} tunnel in the far north-east."] = "道路的尽头是{npc:15395}，就在遥远东北的{area:1769}隧道外。",
		["The wolves roam the fields between Andorhal, {area:200} and the {area:202}. Finish them on the ride back east."] = "狼在安多哈尔、{area:200}和{area:202}之间的田野里游荡。向东骑回去的路上把它们杀完。",
		["The {area:1763} moonwell"] = "{area:1763}的月亮井",
		["Western crater"] = "西部水坑",
		["{area:200} farmhouse"] = "{area:200}的农舍",
		["{npc:10306}: the owlbeasts are in {zone:1452}"] = "{npc:10306}：枭兽在{zone:1452}",
		["{npc:10840}, at the graveyard's south end"] = "{npc:10840}，在墓地南端",
		["{npc:11554}, at the south edge of the camp"] = "{npc:11554}，在营地南缘",
		["{npc:1855}'s hunts are in the {zone:1423}: keep them for later."] = "{npc:1855}的狩猎任务在{zone:1423}：留到之后。",
		["{npc:9529}, just west of the camp"] = "{npc:9529}，在营地正西",
		["{npc:9529}, on the west side of the Sanctuary"] = "{npc:9529}，在翡翠圣地西侧",
		["{npc:9996}'s kitten"] = "{npc:9996}的小猫",
		["{quest:5210} goes to {area:2268}: keep it for later."] = "{quest:5210}要前往{area:2268}：留到之后。",
		["{quest:8470}, a rare drop"] = "{quest:8470}，稀有掉落",
} end)()
t.guides["forever/horde/50-60/03-winterspring"] = (function() return {
