t.guides["forever/legacy/legacy-challenges"] = (function() return {
		["Adventure: explore the world map"] = "冒险：探索世界地图",
		["Adventure: {npc:16042}"] = "冒险：{npc:16042}",
		["Classes give 27 points: every class reaching 25, 45 and 60. They count once per class across your account, so a second character of a class you already raised adds nothing; a new class does. The first character to reach 25 usually unlocks the Legacy System itself."] = "职业共可获得27点：每个职业达到25、45和60级。它们在整个账号中每个职业只计一次，所以已经练过的职业再练一个角色不会增加点数；新职业则会。第一个达到25级的角色通常会解锁传承系统本身。",
		["Classes: level 25"] = "职业：25级",
		["Classes: level 45"] = "职业：45级",
		["Classes: level 60"] = "职业：60级",
		["Dire Maul East"] = "厄运之槌（东）",
		["Dire Maul North"] = "厄运之槌（北）",
		["Dire Maul West"] = "厄运之槌（西）",
		["Dungeons: level 15-25"] = "地下城：15-25级",
		["Dungeons: level 26-45"] = "地下城：26-45级",
		["Dungeons: level 46-60"] = "地下城：46-60级",
		["Each crafting profession gives 3 points, at 150, 225 and 300. Ranks count once per profession across your account. Follow the Polestar guide \"{skill:171} 1-300\" (Professions). A crafting profession at 150 also unlocks the Legacy System."] = "每个制造专业可获得3点，分别在150、225和300。每个等级在整个账号中每个专业只计一次。按照 Polestar 指南“{skill:171} 1-300”（专业）进行。制造专业达到150也会解锁传承系统。",
		["Follow the Polestar guide \"{skill:164} 1-300\" (Professions)."] = "按照 Polestar 指南“{skill:164} 1-300”（专业）进行。",
		["Follow the Polestar guide \"{skill:165} 1-300\" (Professions)."] = "按照 Polestar 指南“{skill:165} 1-300”（专业）进行。",
		["Follow the Polestar guide \"{skill:197} 1-300\" (Professions)."] = "按照 Polestar 指南“{skill:197} 1-300”（专业）进行。",
		["Follow the Polestar guide \"{skill:202} 1-300\" (Professions)."] = "按照 Polestar 指南“{skill:202} 1-300”（专业）进行。",
		["Follow the Polestar guide \"{skill:333} 1-300\" (Professions)."] = "按照 Polestar 指南“{skill:333} 1-300”（专业）进行。",
		["Legacy Challenges"] = "传承挑战",
		["Level 45 with this character's class."] = "用这个角色的职业达到45级。",
		["Level 60 with this character's class."] = "用这个角色的职业达到60级。",
		["Lower {area:1583}"] = "{area:1583}下层",
		["PvP: Field of Honor"] = "PvP：Field of Honor",
		["PvP: battleground reputations (Alliance)"] = "PvP：战场声望（联盟）",
		["PvP: battleground reputations (Horde)"] = "PvP：战场声望（部落）",
		["PvP: honor ranks"] = "PvP：荣誉军衔",
		["Raids: Barrow Deeps"] = "团队副本：Barrow Deeps",
		["Raids: Hyjal Summit"] = "团队副本：Hyjal Summit",
		["Raids: {npc:10184}"] = "团队副本：{npc:10184}",
		["Ranks 3, 7, 10, 13 and 14 are a point each. Polestar cannot read your highest rank yet, so tick each one off yourself. Forever's honor rules for reaching a rank have not been published in detail; in Classic, ranks come from your weekly honor standing, and 13-14 take many weeks of top standing."] = "军衔3、7、10、13和14各计1点。Polestar 目前还无法读取你的最高军衔，所以请自行勾选每一项。Forever 达到军衔的荣誉规则尚未详细公布；在经典版中，军衔来自你每周的荣誉排名，13-14级需要连续许多周的顶尖排名。",
		["The Field of Honor PvP season has weekly journey quests; finishing the ones for weeks 4, 7 and 10 is a point each. These quests are new in Forever and not in our data, so tick each one off yourself."] = "Field of Honor PvP赛季有每周的旅程任务；完成第4、7和10周的任务各计1点。这些任务是 Forever 新增的，不在我们的数据中，所以请自行勾选每一项。",
